import type { Request, Response } from 'express';
import { createApiKeySchema } from '../validators/index.js';
import { writeAuditLog } from '../services/audit.js';
import {
  ApiKeyServiceError,
  createApiKeyForTenant,
  listApiKeysForTenant,
  revokeApiKeyForTenant,
} from '../services/apiKeyService.js';

// POST /api/developers/keys — issues a new tenant API key. The plaintext `key` is present in this
// response ONLY: it is never stored, never logged and never retrievable again afterwards
// (AGENTS.md §13). The caller (Agente 02's Developers.tsx) must show it to the admin once and
// tell them to copy it now.
export async function createApiKeyHandler(req: Request, res: Response) {
  const parsed = createApiKeySchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  const apiKey = await createApiKeyForTenant(req.organizationId as string, req.user?.id, {
    name: parsed.data.name,
    expiresAt: parsed.data.expiresAt ? new Date(parsed.data.expiresAt) : null,
  });

  // Audit the creation event itself, never the secret value.
  writeAuditLog(req.organizationId, req.user?.id, 'API_KEY_CREATE', { apiKeyId: apiKey.id, name: apiKey.name });

  return res.status(201).json({
    apiKey: {
      id: apiKey.id,
      name: apiKey.name,
      createdAt: apiKey.createdAt,
      expiresAt: apiKey.expiresAt,
    },
    key: apiKey.key,
  });
}

// GET /api/developers/keys — metadata only (name, createdAt, lastUsedAt, revoked state). Never
// includes the hash or the plaintext key.
export async function listApiKeysHandler(req: Request, res: Response) {
  const apiKeys = await listApiKeysForTenant(req.organizationId as string);
  return res.json({ apiKeys });
}

// DELETE /api/developers/keys/:id and POST /api/developers/keys/:id/revoke — both revoke the key
// immediately (no cache, checked live by the auth middleware on every request going forward).
export async function revokeApiKeyHandler(req: Request, res: Response) {
  try {
    const apiKey = await revokeApiKeyForTenant(req.organizationId as string, String(req.params.id));
    writeAuditLog(req.organizationId, req.user?.id, 'API_KEY_REVOKE', { apiKeyId: apiKey.id });
    return res.json({ success: true, apiKey });
  } catch (err: any) {
    if (err instanceof ApiKeyServiceError) return res.status(err.status).json({ error: err.message });
    throw err;
  }
}

import { logger } from '@/lib/logger';
import type { Request, Response } from 'express';
import { loginSchema, registerSchema } from '../validators/index.js';
import { z } from 'zod';

const tokenSchema = z.object({
  token: z.string().optional()
});
import { register, login, refreshSession, AuthError } from '../services/authService.js';
import { writeAuditLog } from '../services/audit.js';
import { createMetric } from '../repositories/metricRepository.js';
import { getPermissionsForRoleName } from '../repositories/roleRepository.js';
import { setCookie, setLoggedInCookie, ACCESS_TOKEN_MAX_AGE_MS, REFRESH_TOKEN_MAX_AGE_MS } from '../lib/cookies.js';

export async function registerHandler(req: Request, res: Response) {
  const parsed = registerSchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: parsed.error.issues[0].message });
  }

  const { email, password, companyName } = parsed.data;

  try {
    const result = await register(email, password, companyName);
    writeAuditLog(result.organizationId, result.user.id, 'USER_REGISTER', {});
    setCookie(res, 'access_token', result.token, ACCESS_TOKEN_MAX_AGE_MS);
    setLoggedInCookie(res);
    setCookie(res, 'refresh_token', result.refreshToken, REFRESH_TOKEN_MAX_AGE_MS);
    return res.json(result);
  } catch (err: unknown) {
    logger.error('Register Error', err);
    if (err instanceof AuthError) {
      return res.status(err.status).json({ error: err.message });
    }
    return res.status(500).json({ error: 'Erro interno no servidor' });
  }
}

export async function loginHandler(req: Request, res: Response) {
  const parsed = loginSchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: parsed.error.issues[0].message });
  }

  const { email, password } = parsed.data;

  try {
    const result = await login(email, password);
    writeAuditLog(result.organizationId, result.user.id, 'USER_LOGIN', {});
    createMetric(result.organizationId, result.user.id, { name: 'user_login', value: 1, tags: { userId: result.user.id } });
    setCookie(res, 'access_token', result.token, ACCESS_TOKEN_MAX_AGE_MS);
    setLoggedInCookie(res);
    setCookie(res, 'refresh_token', result.refreshToken, REFRESH_TOKEN_MAX_AGE_MS);
    return res.json(result);
  } catch (err: unknown) {
    logger.error('Login Error', err);
    if (err instanceof AuthError) {
      return res.status(err.status).json({ error: err.message });
    }
    return res.status(500).json({ error: 'Erro interno no servidor' });
  }
}

export async function refreshHandler(req: Request, res: Response) {
  const parsed = tokenSchema.safeParse(req.body);
  const refreshToken = parsed.success ? parsed.data.token : req.cookies?.refresh_token;

  if (!refreshToken) {
    return res.status(401).json({ error: 'Refresh token não fornecido.' });
  }

  try {
    const result = await refreshSession(refreshToken);
    if (!result) {
      res.clearCookie('access_token');
      res.clearCookie('refresh_token');
      return res.status(401).json({ error: 'Refresh token inválido.' });
    }
    setCookie(res, 'access_token', result.token, ACCESS_TOKEN_MAX_AGE_MS);
    setLoggedInCookie(res);
    return res.json(result);
  } catch (err: any) {
    logger.error('Refresh Token Error', err);
    return res.status(500).json({ error: 'Erro interno no servidor.' });
  }
}

export async function logoutHandler(_req: Request, res: Response) {
  res.clearCookie('access_token');
  res.clearCookie('refresh_token');
  res.clearCookie('logged_in');
  return res.json({ success: true, message: 'Logout realizado com sucesso' });
}

// Also resolves the caller's effective Permission set live (never trusted from the JWT claim) so
// the frontend can decide what to show (e.g. the LiveSupervisor "intervene" control) without a
// hardcoded role-name allowlist. This is UX-only information for the client — every
// permission-gated action must still be enforced authoritatively server-side (requirePermission /
// hasPermission in src/middlewares/rbac.ts), never trusted from this response alone.
export async function meHandler(req: Request, res: Response) {
  if (!req.user) return res.json({ user: null });
  const permissions = await getPermissionsForRoleName(req.user.role, req.user.organizationId);
  return res.json({ user: { ...req.user, permissions } });
}

import type { Request, Response } from 'express';
import { changePlanSchema } from '../validators/index.js';
import { logger } from '@/lib/logger';
import { writeAuditLog } from '../services/audit.js';
import {
  changePlan,
  getWalletSummary,
  listAvailablePlans,
  listTransactions,
  PlanNotFoundError,
  ProrationNotSupportedError,
} from '../services/billingService.js';
import { createNotification } from '../services/notificationService.js';

const BILLING_DEFAULT_PAGE_SIZE = 20;
const BILLING_MAX_PAGE_SIZE = 100;

function parsePagination(rawPage: unknown, rawPageSize: unknown): { page: number; pageSize: number } {
  const page = Math.max(1, Number.parseInt(String(rawPage ?? '1'), 10) || 1);
  const pageSize = Math.min(
    BILLING_MAX_PAGE_SIZE,
    Math.max(1, Number.parseInt(String(rawPageSize ?? BILLING_DEFAULT_PAGE_SIZE), 10) || BILLING_DEFAULT_PAGE_SIZE)
  );
  return { page, pageSize };
}

// GET /api/billing/summary — wallet balance + current plan for the "Saldo em Carteira"/"Plano
// Atual" cards. `wallet: null` is a real, explicit state (tenant never onboarded to billing yet),
// not an error — the frontend renders it as an empty state (AGENTS.md §14).
export async function getWalletSummaryHandler(req: Request, res: Response) {
  const wallet = await getWalletSummary(req.organizationId!);
  return res.json({ wallet });
}

// GET /api/billing/transactions — paginated "Histórico de Uso" table, tenant-scoped
// (req.organizationId always comes from requireTenant, never from a query param — AGENTS.md §15).
export async function listTransactionsHandler(req: Request, res: Response) {
  const { page, pageSize } = parsePagination(req.query.page, req.query.pageSize);
  const { items, total } = await listTransactions(req.organizationId!, { page, pageSize });
  return res.json({
    items,
    page,
    pageSize,
    total,
    totalPages: Math.max(1, Math.ceil(total / pageSize)),
  });
}

// GET /api/billing/plans — global plan catalog for the "Gerenciar Assinatura" flow.
export async function listPlansHandler(_req: Request, res: Response) {
  const plans = await listAvailablePlans();
  return res.json({ plans });
}

// POST /api/billing/change-plan — upgrade/downgrade. Only `effectiveAt: 'immediate'` is
// implemented (see ProrationNotSupportedError in billingService.ts for the documented
// limitation); a request for `next_cycle` gets a clear 400, not a silent fallback to immediate.
export async function changePlanHandler(req: Request, res: Response) {
  const parsed = changePlanSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  try {
    const wallet = await changePlan(
      req.organizationId!,
      parsed.data.planId,
      req.user?.id,
      parsed.data.effectiveAt ?? 'immediate'
    );
    writeAuditLog(req.organizationId, req.user?.id, 'BILLING_PLAN_CHANGED', { planId: parsed.data.planId });
    // Best-effort: a notification write failing must never fail the plan change itself (the
    // money/plan side-effect already succeeded). See notificationService.ts module doc — this is
    // the first of potentially several domains calling the same generic entry point, not a
    // billing-only notification path.
    createNotification({
      userId: req.user?.id,
      title: 'Plano atualizado',
      message: `Seu plano foi alterado com sucesso para ${wallet.planName ?? parsed.data.planId}.`,
    }).catch((err) => {
      logger.error('Failed to create plan-change notification', { err, userId: req.user?.id });
    });
    return res.json({ wallet });
  } catch (err: any) {
    if (err instanceof PlanNotFoundError) return res.status(404).json({ error: err.message });
    if (err instanceof ProrationNotSupportedError) return res.status(400).json({ error: err.message });
    throw err;
  }
}

import type { Request, Response } from 'express';
import { callLogSchema } from '../validators/index.js';
import { listCallLogs, createCallLog, updateCallLog, deleteCallLog, NotFoundError } from '../services/callLogService.js';
import { writeAuditLog } from '../services/audit.js';

export async function listCallLogsHandler(req: Request, res: Response) {
  const logs = await listCallLogs(req.organizationId!);
  return res.json({ callLogs: logs });
}

export async function createCallLogHandler(req: Request, res: Response) {
  const parsed = callLogSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  const log = await createCallLog(req.organizationId!, req.user?.id ?? null, parsed.data);
  if (req.user) writeAuditLog(req.organizationId, req.user.id, 'CALL_LOG_CREATE', { logId: log.id });
  return res.json({ success: true, log });
}

export async function updateCallLogHandler(req: Request, res: Response) {
  const parsed = callLogSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  try {
    const log = await updateCallLog(String(req.params.id), req.organizationId!, parsed.data);
    return res.json({ success: true, log });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

export async function deleteCallLogHandler(req: Request, res: Response) {
  try {
    await deleteCallLog(String(req.params.id), req.organizationId!);
    return res.json({ success: true, message: 'Log excluído com sucesso.' });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

