import { createHash } from 'node:crypto';
import { Redis } from 'ioredis';
import { getRedisUrl, getRedisRetryStrategy } from '../../../lib/env.js';
import { logger } from '@/lib/logger';

/**
 * Thrown when we cannot determine whether a webhook delivery is a duplicate (e.g. Redis is
 * unreachable). Callers MUST treat this as "fail closed" — reject the request — rather than
 * proceeding as if the delivery were new. This mirrors the antivirus "fail closed" policy: a
 * real outbound call or a CRM result update must never be replayed just because our dedup store
 * happened to be down for one request.
 */
export class IdempotencyCheckFailedError extends Error {
  constructor(cause: unknown) {
    super('Não foi possível verificar idempotência do webhook (armazenamento indisponível).');
    this.name = 'IdempotencyCheckFailedError';
    this.cause = cause;
  }
}

// Lazily constructed, shared across calls within this process. Cloud Run can run multiple
// instances of this service, so this Redis-backed store — not an in-memory Map — is what makes
// the dedup check work across instances, not just within one.
let redisClient: Redis | null = null;

function getClient(): Redis {
  if (!redisClient) {
    redisClient = new Redis(getRedisUrl(), {
      maxRetriesPerRequest: 1,
      connectTimeout: 2000,
      commandTimeout: 2000,
      retryStrategy: getRedisRetryStrategy(),
    });
    redisClient.on('error', (err: Error) => {
      logger.error('Webhook idempotency Redis client error', err.message);
    });
  }
  return redisClient;
}

/** Test-only hook to swap in a fake client and reset state between test cases. */
export function __setIdempotencyClientForTests(client: Redis | null): void {
  redisClient = client;
}

export const ATLASGR_OUTBOUND_IDEMPOTENCY_PREFIX = 'idempotency:atlasgr-outbound-call:';
export const BLAND_CALLBACK_IDEMPOTENCY_PREFIX = 'idempotency:bland-call-result:';

/** Default dedup window: long enough to absorb realistic webhook-retry storms (most providers give
 * up retrying well within a day), short enough that a genuinely new call to the same lead/number
 * later isn't silently dropped forever. Configurable because "realistic" depends on AtlasGR's own
 * retry policy, which this repo doesn't control. */
export const DEFAULT_IDEMPOTENCY_TTL_SECONDS = Number(
  process.env.ATLASGR_WEBHOOK_IDEMPOTENCY_TTL_SECONDS ?? 24 * 60 * 60,
);

const CALLBACK_PROCESSING_TTL_SECONDS = 60;

/**
 * Derives a stable dedup key for an AtlasGR outbound-call webhook delivery.
 *
 * Prefers `leadId` when AtlasGR supplies one (stable across redeliveries of the same event).
 * Falls back to a hash of the normalized business payload so that even today's contract — which
 * has no lead identifier at all — still gets real protection against duplicate redelivery of the
 * exact same request.
 */
export function buildAtlasGROutboundIdempotencyKey(payload: {
  leadId?: string;
  phoneNumber: string;
  name: string;
  company: string;
}): string {
  if (payload.leadId) {
    return `${ATLASGR_OUTBOUND_IDEMPOTENCY_PREFIX}lead:${payload.leadId}`;
  }
  const normalized = [payload.phoneNumber.replace(/\D/g, ''), payload.name.trim().toLowerCase(), payload.company.trim().toLowerCase()].join('|');
  const hash = createHash('sha256').update(normalized).digest('hex');
  return `${ATLASGR_OUTBOUND_IDEMPOTENCY_PREFIX}hash:${hash}`;
}

/** Bland callbacks carry a provider-generated immutable call id, which is the ideal dedup key. */
export function buildBlandCallbackIdempotencyKey(callId: string): string {
  return `${BLAND_CALLBACK_IDEMPOTENCY_PREFIX}${callId.trim()}`;
}

/**
 * Atomically claims a dedup key. Returns `true` the first time a given key is claimed (caller
 * should proceed), `false` if the key was already claimed within the TTL window (caller must treat
 * this as a duplicate delivery and must NOT repeat the side effect).
 *
 * Throws `IdempotencyCheckFailedError` if the check itself could not be performed — always treat
 * that as "duplicate/unsafe", never as "safe to proceed".
 */
export async function claimIdempotencyKey(
  key: string,
  ttlSeconds: number = DEFAULT_IDEMPOTENCY_TTL_SECONDS,
): Promise<boolean> {
  try {
    const client = getClient();
    const result = await client.set(key, '1', 'EX', ttlSeconds, 'NX');
    return result === 'OK';
  } catch (error: any) {
    throw new IdempotencyCheckFailedError(error);
  }
}

export type CallbackProcessingState = 'acquired' | 'duplicate' | 'in_progress';

/**
 * Callback forwarding needs a two-phase dedup state instead of the one-shot outbound claim.
 * `processing` is deliberately short-lived: if the worker dies after claiming but before AtlasGR
 * acknowledges the result, a provider retry can take over after one minute. `done` is kept for the
 * normal 24h dedup window and makes repeated successful callbacks cheap no-ops.
 */
export async function beginBlandCallbackProcessing(callId: string): Promise<CallbackProcessingState> {
  const key = buildBlandCallbackIdempotencyKey(callId);
  try {
    const client = getClient();
    const claimed = await client.set(key, 'processing', 'EX', CALLBACK_PROCESSING_TTL_SECONDS, 'NX');
    if (claimed === 'OK') return 'acquired';

    const current = await client.get(key);
    return current === 'done' ? 'duplicate' : 'in_progress';
  } catch (error: any) {
    throw new IdempotencyCheckFailedError(error);
  }
}

/** Marks a forwarded callback as durably completed for the regular dedup window. */
export async function completeBlandCallbackProcessing(
  callId: string,
  ttlSeconds: number = DEFAULT_IDEMPOTENCY_TTL_SECONDS,
): Promise<void> {
  try {
    await getClient().set(buildBlandCallbackIdempotencyKey(callId), 'done', 'EX', ttlSeconds);
  } catch (error: any) {
    throw new IdempotencyCheckFailedError(error);
  }
}

/**
 * Releases a callback processing lock when AtlasGR definitely did not acknowledge the delivery.
 * That lets a provider retry attempt the forwarding again instead of silently losing the result.
 */
export async function releaseBlandCallbackProcessing(callId: string): Promise<void> {
  try {
    await getClient().del(buildBlandCallbackIdempotencyKey(callId));
  } catch (error: any) {
    throw new IdempotencyCheckFailedError(error);
  }
}

import express from 'express';
import { logger } from '@/lib/logger';
import {
  voiceProspectingService,
  BlandConfigurationError,
  ExternalAiConsentRequiredError,
} from '../services/voice.service.js';
import { atlasGROutboundPayloadSchema, blandCallResultSchema } from '../validators/atlasgr.schema.js';
import { safeEqual } from '../lib/safeCompare.js';
import {
  beginBlandCallbackProcessing,
  completeBlandCallbackProcessing,
  IdempotencyCheckFailedError,
  releaseBlandCallbackProcessing,
} from '../lib/webhookIdempotency.js';
import { upsertAtlasGRCallResult } from '../../../repositories/atlasGRCallResultRepository.js';

const router = express.Router();

// This router is mounted before the global express.json() (see server.ts — it also needs to run
// before csrfProtection, since both routes below are server-to-server webhooks authenticated by
// their own secret, not by session cookie/Origin). It therefore owns its JSON body parser.
router.use(express.json());

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
}

function asString(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

function asNumber(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : 0;
}

function asBoolean(value: unknown, fallback: boolean): boolean {
  return typeof value === 'boolean' ? value : fallback;
}

/**
 * Authenticates the AtlasGR CRM as the caller via a pre-shared secret sent in a custom header.
 * Fails closed: if the secret isn't configured server-side, every request is rejected rather than
 * silently accepted.
 */
function validateAtlasGRSecret(req: express.Request, res: express.Response, next: express.NextFunction) {
  const expectedSecret = process.env.ATLASGR_WEBHOOK_SECRET;
  if (!expectedSecret) {
    logger.error('AtlasGR webhook rejected: ATLASGR_WEBHOOK_SECRET is not configured (failing closed)');
    return res.status(503).json({ error: 'Integração AtlasGR não está configurada.' });
    return;
  }

  const provided = req.headers['x-atlasgr-webhook-secret'];
  if (typeof provided !== 'string' || !safeEqual(provided, expectedSecret)) {
    logger.warn('AtlasGR webhook rejected: missing or invalid shared secret', {
      hasHeader: typeof provided === 'string',
    });
    return res.status(401).json({ error: 'Não autorizado.' });
    return;
  }

  return next();
}

/**
 * Authenticates the Bland AI call-result callback via a token embedded in the callback URL itself
 * (Bland AI's outbound-call API takes a plain `webhook` URL with no custom-header support, so a
 * shared secret has to travel in the path).
 */
function validateBlandCallbackToken(req: express.Request, res: express.Response, next: express.NextFunction) {
  const expectedToken = process.env.BLAND_WEBHOOK_TOKEN;
  if (!expectedToken) {
    logger.error('Bland AI callback rejected: BLAND_WEBHOOK_TOKEN is not configured (failing closed)');
    return res.status(503).json({ error: 'Callback da Bland AI não está configurado.' });
    return;
  }

  const provided = req.params.token;
  if (typeof provided !== 'string' || !safeEqual(provided, expectedToken)) {
    logger.warn('Bland AI callback rejected: invalid token');
    return res.status(403).json({ error: 'Token inválido.' });
    return;
  }

  return next();
}

router.post('/webhook/atlasgr/outbound', validateAtlasGRSecret, async (req, res) => {
  const parsed = atlasGROutboundPayloadSchema.safeParse(req.body);
  if (!parsed.success) {
    logger.warn('AtlasGR webhook rejected: invalid payload', { issues: parsed.error.issues });
    return res.status(400).json({ error: 'Payload inválido.', issues: parsed.error.issues.map((i) => i.message) });
    return;
  }

  try {
    const result = await voiceProspectingService.triggerOutboundCall(parsed.data);
    return res.status(200).json(result);
  } catch (error: any) {
    if (error instanceof ExternalAiConsentRequiredError) {
      logger.warn('AtlasGR webhook rejected: external AI consent is not granted for the configured tenant');
      return res.status(403).json({
        error: 'Consentimento para processamento por provedor externo de IA é obrigatório.',
        code: 'AI_PROVIDER_CONSENT_REQUIRED',
      });
      return;
    }
    if (error instanceof IdempotencyCheckFailedError) {
      logger.error('AtlasGR webhook: idempotency check failed, rejecting to avoid a duplicate call', {
        error: error.message,
      });
      return res.status(503).json({ error: 'Não foi possível processar o webhook no momento. Tente novamente.' });
      return;
    }
    if (error instanceof BlandConfigurationError) {
      logger.error('AtlasGR webhook: Bland AI integration is misconfigured', { error: error.message });
      return res.status(503).json({ error: 'Integração com Bland AI não está configurada.' });
      return;
    }
    logger.error('AtlasGR webhook: failed to process outbound call request', {
      error: error instanceof Error ? error.message : String(error),
    });
    return res.status(502).json({ error: 'Failed to process AtlasGR webhook' });
  }
});

router.post('/webhooks/bland/:token', validateBlandCallbackToken, async (req, res) => {
  const parsed = blandCallResultSchema.safeParse(req.body);
  if (!parsed.success) {
    logger.warn('Bland AI callback rejected: invalid payload', { issues: parsed.error.issues });
    return res.status(400).json({ error: 'Payload inválido.' });
    return;
  }

  const data = parsed.data as typeof parsed.data & Record<string, unknown>;
  const callId = data.call_id;
  logger.info('Received Bland AI call result callback', {
    callId,
    status: data.status,
  });

  // There must never be a built-in credential or localhost destination in this production path.
  // Both values are external configuration and the callback fails closed when either is absent.
  const atlasBaseUrl = process.env.ATLASGR_BASE_URL?.trim();
  const webhookSecret = process.env.ATLASGR_WEBHOOK_SECRET?.trim();
  if (!atlasBaseUrl || !webhookSecret) {
    logger.error('Bland AI callback cannot be forwarded: AtlasGR destination or signing secret is missing', {
      callId,
      hasBaseUrl: Boolean(atlasBaseUrl),
      hasSecret: Boolean(webhookSecret),
    });
    return res.status(503).json({ error: 'Integração de retorno com AtlasGR não está configurada.' });
    return;
  }

  let processingState: Awaited<ReturnType<typeof beginBlandCallbackProcessing>>;
  try {
    processingState = await beginBlandCallbackProcessing(callId);
  } catch (error: any) {
    logger.error('Bland AI callback rejected because idempotency storage is unavailable', {
      callId,
      error: error instanceof Error ? error.message : String(error),
    });
    return res.status(503).json({ error: 'Não foi possível verificar idempotência do callback.' });
    return;
  }

  if (processingState === 'duplicate') {
    return res.status(200).json({ received: true, duplicate: true });
    return;
  }

  if (processingState === 'in_progress') {
    // Ask the provider to retry later instead of executing the same CRM side effect concurrently.
    return res.status(503).json({ error: 'Callback já está sendo processado. Tente novamente.' });
    return;
  }

  const variables = asRecord(data.variables);
  const forwardPayload = {
    call_id: callId,
    phone_number: asString(data.to) || asString(variables.phone_number),
    concatenated_transcript: asString(data.concatenated_transcript),
    summary: asString(data.summary),
    recording_url: asString(data.recording_url),
    call_length: asNumber(data.call_length),
    completed: asBoolean(data.completed, true),
  };

  // Persist the call result for audit/historical lookup before attempting to forward it to
  // AtlasGR, so a later forwarding failure doesn't also cost us the only record that Bland AI
  // reported this result at all (see
  // .agents/handoffs/onda-4/01-para-06-persistir-resultado-bland-pronto.md). Fire-and-forget on
  // purpose: this local bookkeeping must never fail or delay the response to Bland AI, but a
  // failure here is never swallowed silently either — it is always logged.
  // `organizationId` is best-effort only: `ATLASGR_TENANT_ID` identifies the tenant at call *dispatch*
  // time, but that id is never sent to Bland AI as call metadata and never comes back in this
  // callback, so it cannot be verified against the actual call — see the `AtlasGRCallResult`
  // model comment in prisma/schema.prisma for the full rationale.
  upsertAtlasGRCallResult({
    callId,
    status: data.status ?? null,
    completed: forwardPayload.completed,
    callLength: forwardPayload.call_length || null,
    leadId: asString(variables.lead_id) || null,
    organizationId: process.env.ATLASGR_TENANT_ID?.trim() || null,
  }).catch((error) => {
    logger.error('Failed to persist AtlasGR/Bland AI call result', {
      callId,
      error: error instanceof Error ? error.message : String(error),
    });
  });

  try {
    const response = await fetch(`${atlasBaseUrl.replace(/\/$/, '')}/api/webhooks/voice-result`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-atlasgr-webhook-secret': webhookSecret,
        // Lets the receiving CRM make its own update idempotent even if this service crashes after
        // AtlasGR accepts the request but before Redis is marked `done`.
        'x-idempotency-key': `bland-call-result:${callId}`,
      },
      body: JSON.stringify(forwardPayload),
    });

    if (!response.ok) {
      throw new Error(`AtlasGR voice-result returned HTTP ${response.status}`);
    }

    await completeBlandCallbackProcessing(callId);
    logger.info('Successfully forwarded voice call result to AtlasGR', { callId });
    return res.status(200).json({ received: true, duplicate: false });
  } catch (error: any) {
    try {
      await releaseBlandCallbackProcessing(callId);
    } catch (releaseError: any) {
      logger.error('Failed to release Bland callback processing lock after forwarding failure', {
        callId,
        error: releaseError instanceof Error ? releaseError.message : String(releaseError),
      });
    }

    logger.error('Failed to forward voice call result to AtlasGR CRM', {
      callId,
      error: error instanceof Error ? error.message : String(error),
    });
    return res.status(502).json({ error: 'Falha ao encaminhar resultado da chamada para AtlasGR.' });
  }
});

