// Field-name-based redaction for known secret-bearing keys. This catches secrets passed as
// structured metadata (e.g. `logger.error('...', { apiKey })`) or embedded one level deep in an
// object (e.g. a provider's raw response echoed back for debugging). It does not scan arbitrary
// string values for secret-shaped content — call sites must still avoid interpolating raw
// credentials into the message string itself.
const SECRET_FIELD_NAMES = [
  'password',
  'passwordHash',
  'token',
  'accessToken',
  'access_token',
  'refreshToken',
  'refresh_token',
  'apiKey',
  'api_key',
  'apikey',
  'secret',
  'clientSecret',
  'client_secret',
  'authorization',
  'Authorization',
  'jwtSecret',
  'JWT_SECRET',
  'REFRESH_TOKEN_SECRET',
  'WEBHOOK_SIGNING_SECRET',
  'TWILIO_AUTH_TOKEN',
  'BLAND_API_KEY',
  'ELEVENLABS_API_KEY',
  'OPENAI_API_KEY',
  'ANTHROPIC_API_KEY',
  'GEMINI_API_KEY',
  'S3_SECRET_KEY',
  'S3_ACCESS_KEY',
  'OIDC_CLIENT_SECRET',
];

const redactPaths = SECRET_FIELD_NAMES.flatMap((name) => [name, `*.${name}`]);

const base = pino({
  level: process.env.LOG_LEVEL || (process.env.NODE_ENV === 'production' ? 'info' : 'debug'),
  redact: {
    paths: redactPaths,
    censor: '[REDACTED]',
  },
  serializers: {
    err: pino.stdSerializers.err,
  },
  base: undefined, // omit pid/hostname noise; Cloud Run already attaches that context
});

function normalizeMeta(meta: LogMeta): Record<string, unknown> | undefined {
  if (meta === undefined) return undefined;
  if (meta instanceof Error) {
    return { err: meta };
  }
  if (typeof meta === 'object' && meta !== null) {
    return meta as Record<string, unknown>;
  }
  return { detail: meta };
}

// --- OTel Logs bridge -------------------------------------------------------------------------
// See .agents/handoffs/onda-4/10-para-04-otel-metrics-logs-nao-exportados.md: pino only ever wrote
// to stdout, with no path into the OTel pipeline the otel-collector already exposes (`logs`
// pipeline -> Loki). `logs.getLogger(...)` is safe to call unconditionally: until
// `lib/otelInitializer.ts` registers a real LoggerProvider (via `logRecordProcessors`), the global
// Logs API hands back a no-op logger and `emit(...)` below is a harmless no-op — the same pattern
// already relied on for traces/metrics elsewhere in this codebase.
const otelLogger: OtelLogger = logs.getLogger('birth-voices-app-logger');

const OTEL_SEVERITY: Record<'debug' | 'info' | 'warn' | 'error', { number: SeverityNumber; text: string }> = {
  debug: { number: SeverityNumber.DEBUG, text: 'DEBUG' },
  info: { number: SeverityNumber.INFO, text: 'INFO' },
  warn: { number: SeverityNumber.WARN, text: 'WARN' },
  error: { number: SeverityNumber.ERROR, text: 'ERROR' },
};

function isSecretKey(key: string): boolean {
  return SECRET_FIELD_NAMES.some((name) => name.toLowerCase() === key.toLowerCase());
}

// Redacts the same field names/depth as the pino `redact` config above (top-level + one level
// nested, matching the `name`/`*.name` path pairs in `redactPaths`). Applied independently of
// pino's own redaction because this object is exported down a second, separate path (OTel Logs ->
// otel-collector -> Loki) and must never rely on pino's internal serialization to have already
// scrubbed it in place.
function redactSecretsForExport(input: Record<string, unknown>, depth = 1): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(input)) {
    if (isSecretKey(key)) {
      out[key] = '[REDACTED]';
    } else if (depth > 0 && value !== null && typeof value === 'object' && !(value instanceof Error) && !Array.isArray(value)) {
      out[key] = redactSecretsForExport(value as Record<string, unknown>, depth - 1);
    } else {
      out[key] = value;
    }
  }
  return out;
}

// OTel LogRecord attribute values must be strings/numbers/booleans (or homogeneous arrays of
// those) — flatten anything else (Error objects, nested objects/arrays already past the
// redaction pass) into a string so `emit(...)` never throws on a shape it doesn't accept.
function toAttributeValue(value: unknown): string | number | boolean {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return value;
  if (value instanceof Error) {
    return JSON.stringify({ name: value.name, message: value.message, stack: value.stack });
  }
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function emitOtelLogRecord(level: 'debug' | 'info' | 'warn' | 'error', message: string, payload: Record<string, unknown>) {
  try {
    const severity = OTEL_SEVERITY[level];
    const redacted = redactSecretsForExport(payload);
    const attributes: Record<string, string | number | boolean> = {};
    for (const [key, value] of Object.entries(redacted)) {
      attributes[key] = toAttributeValue(value);
    }
    otelLogger.emit({
      severityNumber: severity.number,
      severityText: severity.text,
      body: message,
      attributes,
    });
  } catch (bridgeError: any) {
    // Telemetry export must never break the actual application log call.
    base.warn({ err: bridgeError }, 'Failed to emit log record to OTel Logs bridge');
  }
}
// -----------------------------------------------------------------------------------------------

function log(level: 'debug' | 'info' | 'warn' | 'error', message: string, meta?: LogMeta) {
  const requestId = getRequestId();
  const normalized = normalizeMeta(meta);
  const payload = {
    ...(requestId ? { requestId } : {}),
    ...(normalized || {}),
  };
  base[level](payload, message);
  emitOtelLogRecord(level, message, payload);
}

export const logger = {
  debug(message: string, meta?: LogMeta) {
    log('debug', message, meta);
  },
  info(message: string, meta?: LogMeta) {
    log('info', message, meta);
  },
  warn(message: string, meta?: LogMeta) {
    log('warn', message, meta);
  },
  error(message: string, meta?: LogMeta) {
    log('error', message, meta);
  },
};

import type express from 'express';
import { Redis } from 'ioredis';
import { verifyToken, type TokenPayload } from '../lib/auth-tokens.js';
import { refreshSession } from '../services/authService.js';
import { setCookie, ACCESS_TOKEN_MAX_AGE_MS } from '../lib/cookies.js';
import { authenticateApiKey, isApiKeyFormat } from '../services/apiKeyService.js';
import { getRedisUrl, getRedisRetryStrategy } from '../lib/env.js';
import { logger } from '@/lib/logger';

export const csrfProtection = (req: express.Request, res: express.Response, next: express.NextFunction) => {
  if (['POST', 'PUT', 'DELETE'].includes(req.method)) {
    // Requests authenticated via a Bearer token in the Authorization header — rather than the
    // ambient session cookie — are not exploitable via CSRF: a malicious page cannot attach an
    // arbitrary Authorization header to a cross-site request, and cors() already restricts which
    // origins may read the response of a JS-initiated cross-origin request. This unblocks
    // legitimate server-to-server callers authenticated this way (e.g. the AtlasGR CRM calling
    // POST /api/voice/outbound with its own bearer token, which never sends an Origin header)
    // without weakening protection for the cookie-authenticated browser path below.
    if (req.headers.authorization?.startsWith('Bearer ')) {
      return next();
    }

    const isProduction = process.env.NODE_ENV === 'production';
    const origin = req.headers.origin;
    const host = req.headers.host;

    if (!origin) {
      // Same-site requests without credentials (e.g. plain HTML form posts) legitimately omit
      // Origin in some browsers, but in production we require it for mutation requests since
      // this is our only CSRF signal — outside production, tooling (tests, curl, etc.) may not send it.
      if (isProduction) {
        return res.status(403).json({ error: 'Validação de origem de segurança (CSRF) falhou.' });
        return;
      }
      return next();
    }

    if (host) {
      try {
        const parsedOrigin = new URL(origin).host;
        if (parsedOrigin !== host) {
          return res.status(403).json({ error: 'Validação de origem de segurança (CSRF) falhou.' });
          return;
        }
      } catch {
        return res.status(403).json({ error: 'Validação de origem de segurança (CSRF) falhou.' });
        return;
      }
    }
  }
  return next();
};

function setAccessTokenCookie(res: express.Response, token: string) {
  setCookie(res, 'access_token', token, ACCESS_TOKEN_MAX_AGE_MS);
  // Non-httpOnly UI flag (no sensitive data) so the frontend can tell it has a live session
  // without parsing the httpOnly access_token cookie.
  res.cookie('logged_in', 'true', {
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 86400 * 30 * 1000,
  });
}

// Redis-backed per-API-key rate limiter, applied to every request authenticated via an API key
// (see the `req.apiKeyId` check in attachAuthIfPresent below). Reuses the same increment+expire
// sliding-window pattern already used for the IP-based limiters in server.ts (Agente 00's file,
// not importable here — its limiter factory is a local closure, not exported), rather than
// inventing a different rate-limiting mechanism for this one call site. A Redis outage fails open
// (never blocks an otherwise-valid authenticated request) — same tradeoff server.ts's limiters make.
const API_KEY_RATE_LIMIT = 120;
const API_KEY_RATE_WINDOW_SECONDS = 60;
const rateLimitRedis = new Redis(getRedisUrl(), { maxRetriesPerRequest: 1, connectTimeout: 2000, commandTimeout: 2000, retryStrategy: getRedisRetryStrategy() });
rateLimitRedis.on('error', (err) => logger.error('API key rate limiter Redis error', err));

async function isApiKeyRateLimited(apiKeyId: string): Promise<boolean> {
  const key = `ratelimit:apikey:${apiKeyId}`;
  try {
    const current = await rateLimitRedis.incr(key);
    if (current === 1) {
      await rateLimitRedis.expire(key, API_KEY_RATE_WINDOW_SECONDS);
    }
    return current > API_KEY_RATE_LIMIT;
  } catch {
    return false;
  }
}

export async function getAuthUser(req: express.Request, res?: express.Response): Promise<TokenPayload | null> {
  const bearerToken = req.headers.authorization?.startsWith('Bearer ')
    ? req.headers.authorization.substring(7)
    : undefined;

  // Alternative authentication path: a Bearer token shaped like a tenant API key is resolved
  // against APIKey.keyHash instead of verified as a JWT. This never replaces the JWT flow below —
  // a request with a JWT cookie or a JWT Bearer token is unaffected and keeps working exactly as
  // before. A revoked/expired/unknown key authenticates as nobody (401 downstream via
  // requireTenant), never falls through to try JWT verification on the same string.
  if (bearerToken && isApiKeyFormat(bearerToken)) {
    const result = await authenticateApiKey(bearerToken);
    if (!result) return null;
    req.apiKeyId = result.apiKeyId;
    return result.session;
  }

  let token = req.cookies?.access_token;
  if (!token && bearerToken) {
    token = bearerToken;
  }

  if (token) {
    const decoded = verifyToken(token);
    if (decoded) return decoded;
  }

  const refreshToken = req.cookies?.refresh_token;
  if (refreshToken) {
    const refreshed = await refreshSession(refreshToken);
    if (refreshed) {
      if (res) setAccessTokenCookie(res, refreshed.token);
      return refreshed.session;
    }
  }

  return null;
}

export const attachAuthIfPresent = async (req: express.Request, res: express.Response, next: express.NextFunction) => {
  const session = await getAuthUser(req, res);
  if (session) {
    req.user = session;
    req.organizationId = session.organizationId;

    // Auto-upsert User and Tenant in Dev environment so old JWT cookies don't break fresh databases
    if (process.env.NODE_ENV !== 'production' && session.organizationId) {
      try {
        const { prisma } = await import('../lib/prisma.js');
        await prisma.tenant.upsert({
          where: { id: session.organizationId },
          update: {},
          create: { id: session.organizationId, name: 'Local Dev Tenant' }
        });
        await prisma.user.upsert({
          where: { id: session.id },
          update: {},
          create: {
            id: session.id,
            organizationId: session.organizationId,
            email: session.email || 'dev@local.com',
            companyName: 'Local Dev Corp',
            passwordHash: 'dummy'
          }
        });
      } catch (err: any) {
        console.error('Failed to auto-upsert dev tenant/user:', err);
      }
    }
  }

  // Basic per-key rate limit, applied only to requests that actually authenticated via an API
  // key (req.apiKeyId set inside getAuthUser above) — JWT-authenticated requests are unaffected
  // and continue to rely solely on the IP-based limiters in server.ts.
  if (req.apiKeyId) {
    const limited = await isApiKeyRateLimited(req.apiKeyId);
    if (limited) {
      return res.status(429).json({ error: 'Limite de requisições excedido para esta chave de API. Tente novamente em breve.' });
      return;
    }
  }

  return next();
};

import type { Request, Response } from 'express';
import {
  listNotifications,
  markAllAsRead,
  markAsRead,
  NotificationNotFoundError,
} from '../services/notificationService.js';

const NOTIFICATIONS_DEFAULT_PAGE_SIZE = 20;
const NOTIFICATIONS_MAX_PAGE_SIZE = 100;

function parsePagination(rawPage: unknown, rawPageSize: unknown): { page: number; pageSize: number } {
  const page = Math.max(1, Number.parseInt(String(rawPage ?? '1'), 10) || 1);
  const pageSize = Math.min(
    NOTIFICATIONS_MAX_PAGE_SIZE,
    Math.max(1, Number.parseInt(String(rawPageSize ?? NOTIFICATIONS_DEFAULT_PAGE_SIZE), 10) || NOTIFICATIONS_DEFAULT_PAGE_SIZE)
  );
  return { page, pageSize };
}

// GET /api/notifications — paginated feed for the NotificationCenter panel, plus the unread count
// the bell badge needs. Scoped to `req.user!.id` — never a query/body param — so one user can
// never page through another user's (and therefore another tenant's, AGENTS.md §15/§16 item 12)
// notifications by changing an id in the request.
export async function listNotificationsHandler(req: Request, res: Response) {
  const { page, pageSize } = parsePagination(req.query.page, req.query.pageSize);
  const result = await listNotifications(req.user?.id, { page, pageSize });
  return res.json({
    items: result.items,
    unreadCount: result.unreadCount,
    page,
    pageSize,
    total: result.total,
    totalPages: Math.max(1, Math.ceil(result.total / pageSize)),
  });
}

// POST /api/notifications/:id/read — marks one notification read. Ownership is verified inside
// notificationService/notificationRepository against req.user!.id; a notification belonging to
// another user resolves to the same 404 as one that does not exist at all (AGENTS.md §15 fallback
// convention — never reveal that a resource exists in someone else's account).
export async function markNotificationReadHandler(req: Request, res: Response) {
  try {
    const notification = await markAsRead(String(req.params.id), req.user?.id);
    return res.json({ notification });
  } catch (err: any) {
    if (err instanceof NotificationNotFoundError) {
      return res.status(404).json({ error: 'Notificação não encontrada.' });
    }
    throw err;
  }
}

// POST /api/notifications/read-all — bulk "mark all as read" for the panel header action.
export async function markAllNotificationsReadHandler(req: Request, res: Response) {
  const result = await markAllAsRead(req.user?.id);
  return res.json(result);
}

