import { Prisma } from '@prisma/client';
import * as agentRepository from '../repositories/agentRepository.js';
import * as sessionRepository from '../repositories/sessionRepository.js';
import { getTelephonyProvider } from './telephonyProvider.js';
import type { PhoneSessionMetadata } from './telephonyService.js';
import { logger } from '@/lib/logger';

export class AgentNotFoundError extends Error {}
export class DuplicateCallError extends Error {}

export interface OutboundCallRequest {
  organizationId: string;
  agentId: string;
  /** E.164, validated at the route boundary. */
  targetNumber: string;
  /**
   * Arbitrary caller-supplied facts about who is being called (lead name, company, the reason for
   * the call). Made available to the agent's greeting template and echoed back on the
   * `agent.call.ended` webhook so the originating system can correlate the result.
   */
  context?: Record<string, unknown>;
  /** Per-call override of where `agent.call.ended` is delivered. */
  callbackUrl?: string;
}

export interface OutboundCallResult {
  sessionId: string;
  callSid: string;
  status: string;
}

/**
 * Places an outbound call and returns as soon as Twilio has accepted it — the conversation itself
 * happens later, over the TwiML webhooks, and the outcome arrives via the `agent.call.ended`
 * webhook. Callers get back a sessionId to correlate the two.
 */
export async function initiateOutboundCall(params: OutboundCallRequest): Promise<OutboundCallResult> {
  // Tenant-scoped lookup (not findAgentById) so one tenant can never dial using another's agent.
  const agent = await agentRepository.getAgent(params.agentId, params.organizationId);
  if (!agent) {
    throw new AgentNotFoundError('Agente não encontrado para este tenant.');
  }

  const provider = getTelephonyProvider();
  // Checked before the session is created so a misconfigured deployment fails without leaving an
  // orphaned "active" session behind — which the duplicate guard below would then treat as a real
  // call in flight, blocking this number indefinitely.
  provider.assertConfigured();

  const metadata: PhoneSessionMetadata = {
    direction: 'outbound',
    callSid: null,
    // Only the provider knows the caller ID it will actually use, so this is filled in below.
    from: null,
    to: params.targetNumber,
    context: params.context ?? {},
    callbackUrl: params.callbackUrl ?? null,
    turns: [],
  };

  // Double-submit / retry-of-queue guard: the "is a call already active for this number" check and
  // the session creation happen in one Serializable DB transaction (see
  // createOutboundPhoneSessionIfNoneInFlight) so two near-simultaneous requests for the same
  // tenant+number can never both slip through and dial the same lead twice. A losing concurrent
  // request surfaces here as a Postgres serialization failure (Prisma P2034), not as `inFlight`.
  let claim: Awaited<ReturnType<typeof sessionRepository.createOutboundPhoneSessionIfNoneInFlight>>;
  try {
    claim = await sessionRepository.createOutboundPhoneSessionIfNoneInFlight(
      agent.organizationId,
      agent.id,
      params.targetNumber,
      metadata,
    );
  } catch (err: any) {
    if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === 'P2034') {
      logger.warn('[OutboundCall] Concurrent dial to the same number lost the double-submit race', {
        organizationId: agent.organizationId,
        to: params.targetNumber,
      });
      throw new DuplicateCallError('Já existe uma chamada em andamento para este número.');
    }
    throw err;
  }

  if (claim.inFlight || !claim.session) {
    throw new DuplicateCallError('Já existe uma chamada em andamento para este número.');
  }
  const session = claim.session;

  try {
    const call = await provider.placeCall({ to: params.targetNumber, sessionId: session.id });

    // Persisted as soon as the provider accepts the call rather than when the conversation starts:
    // a call that is never answered never reaches the media callback, and without the id stored
    // here the status callback could not find this session to record the "no answer" outcome.
    metadata.callSid = call.callId;
    metadata.from = call.from;
    await sessionRepository.updateSession(session.id, {
      metadata: metadata as unknown as Prisma.InputJsonValue,
    });

    logger.info('[OutboundCall] Call queued', {
      sessionId: session.id,
      callSid: call.callId,
      provider: provider.name,
      organizationId: agent.organizationId,
      agentId: agent.id,
    });

    return { sessionId: session.id, callSid: call.callId, status: call.status };
  } catch (err: any) {
    // The session was already created, so leaving it "active" would block every future call to
    // this number via the duplicate guard above.
    await sessionRepository.updateSession(session.id, { status: 'failed' });
    logger.error('[OutboundCall] Twilio rejected the call', {
      sessionId: session.id,
      to: params.targetNumber,
      error: err instanceof Error ? err.message : String(err),
    });
    throw err;
  }
}

import { randomUUID } from 'node:crypto';
import { Queue } from 'bullmq';
import { getRedisConnectionOptions } from '../lib/env.js';
import { logger } from '@/lib/logger';
import { resolveActiveEndpointsForEvent } from './webhookEndpointService.js';

/**
 * Envelope documented in docs/webhooks/index.md — consumers verify the signature over exactly
 * this JSON, so field names here are a published contract, not an internal detail.
 */
export interface WebhookPayload {
  id: string;
  type: string;
  timestamp: string;
  organizationId: string;
  data: Record<string, unknown>;
}

export class WebhookService {
  private webhookQueue: Queue;

  constructor() {
    this.webhookQueue = new Queue('webhooks', {
      connection: { ...getRedisConnectionOptions(), maxRetriesPerRequest: null },
    });
  }

  /**
   * Queues an event for delivery. Never throws: webhook delivery is a side effect of whatever
   * business operation produced the event, and must not be able to fail it.
   *
   * @param targetUrl Per-call destination — used for calls that carry their own callback URL
   *                  (e.g. `POST /api/voice/outbound`'s `callbackUrl`). When passed explicitly,
   *                  this legacy path is used as-is and per-tenant endpoints are not consulted —
   *                  the caller already named exactly one destination.
   *
   *                  When omitted, resolves the tenant's configured `TenantWebhookEndpoint`s
   *                  (webhookEndpointService.resolveActiveEndpointsForEvent) and enqueues one
   *                  delivery per active endpoint whose `events` includes this event type (or
   *                  `"*"`). Only when the tenant has NO active endpoint configured at all does
   *                  this fall back to the deployment-wide `WEBHOOK_URL`/`TEST_WEBHOOK_URL` env
   *                  vars — see resolveActiveEndpointsForEvent's `hasAnyActiveEndpoint` doc for why
   *                  a configured-but-non-matching tenant never falls through to that fallback.
   */
  public async dispatch(
    organizationId: string,
    event: string,
    data: Record<string, unknown>,
    targetUrl?: string,
  ): Promise<void> {
    try {
      const payload: WebhookPayload = {
        id: `evt_${randomUUID()}`,
        type: event,
        timestamp: new Date().toISOString(),
        organizationId,
        data,
      };

      if (targetUrl) {
        await this.enqueue({ url: targetUrl, payload });
        logger.info(`[WebhookService] Queued event ${event} for tenant ${organizationId} (explicit targetUrl)`);
        return;
      }

      // Resolution is a real Prisma read against `TenantWebhookEndpoint` (see
      // .agents/handoffs/onda-5/05-para-01-schema-webhook-endpoint-pronto.md). A failure here
      // (e.g. a transient DB outage) must NOT fall through to the deployment-wide env-var
      // fallback below — a tenant that has configured its own endpoints could otherwise have call
      // /lead data delivered to that shared destination during the very outage that made the
      // lookup fail, an unintended cross-destination leak (AGENTS.md §15: fail closed on an
      // ambiguous/error state, never silently downgrade to a different destination). `dispatch()`
      // itself still never throws — the event is just dropped (logged as an error, not a debug
      // line) rather than misdelivered; the caller's business operation is unaffected either way.
      let hasAnyActiveEndpoint = false;
      let targets: { endpointId: string; url: string }[] = [];
      try {
        const resolution = await resolveActiveEndpointsForEvent(organizationId, event);
        hasAnyActiveEndpoint = resolution.hasAnyActiveEndpoint;
        targets = resolution.targets;
      } catch (resolutionError: any) {
        logger.error(
          `[WebhookService] Could not resolve tenant webhook endpoints for tenant ${organizationId} — dropping event ${event} instead of risking delivery to the wrong destination`,
          resolutionError,
        );
        return;
      }

      if (hasAnyActiveEndpoint) {
        if (targets.length === 0) {
          // Tenant has active endpoints, just none subscribed to this event type — a deliberate
          // no-op, never redirected to the deployment-wide fallback (see dispatch's doc comment).
          logger.debug(`[WebhookService] No tenant endpoint subscribed to event ${event} for tenant ${organizationId}`);
          return;
        }
        for (const target of targets) {
          await this.enqueue({ url: target.url, payload, endpointId: target.endpointId });
        }
        logger.info(
          `[WebhookService] Queued event ${event} for tenant ${organizationId} to ${targets.length} tenant endpoint(s)`,
        );
        return;
      }

      const webhookUrl = process.env.WEBHOOK_URL || process.env.TEST_WEBHOOK_URL;
      if (!webhookUrl) {
        logger.debug(`[WebhookService] No webhook URL configured for tenant ${organizationId}`);
        return;
      }

      await this.enqueue({ url: webhookUrl, payload });
      logger.info(`[WebhookService] Queued event ${event} for tenant ${organizationId} (deployment-wide fallback)`);
    } catch (error: any) {
      logger.error(`[WebhookService] Error dispatching webhook event ${event}`, error);
    }
  }

  private async enqueue(job: { url: string; payload: WebhookPayload; endpointId?: string }): Promise<void> {
    await this.webhookQueue.add('send_webhook', job, {
      attempts: 5,
      backoff: {
        type: 'exponential',
        delay: 2000,
      },
    });
  }
}

export const webhookService = new WebhookService();

import { createHmac } from 'node:crypto';
import { Worker, type Job, UnrecoverableError } from 'bullmq';
import { getRedisConnectionOptions } from '../lib/env.js';
import { logger } from '@/lib/logger';
import { isPrivateOrReservedHost } from '../validators/index.js';
import type { WebhookPayload } from './webhook.service.js';
import { findActiveSigningSecretHash } from './webhookEndpointService.js';
import { recordDeliveryResult } from '../repositories/webhookEndpointRepository.js';

/** Matches the 5s timeout published in docs/webhooks/index.md. */
const DELIVERY_TIMEOUT_MS = 5000;

/**
 * Defense-in-depth SSRF guard, re-checked here (not just at the `POST /api/voice/outbound` Zod
 * schema in `src/validators/index.ts`) because `job.data.url` is whatever was enqueued by
 * `webhookService.dispatch(...)`, and that is not guaranteed to always come from a value the
 * inbound schema validated — e.g. `WEBHOOK_URL`/`TEST_WEBHOOK_URL` env vars today, and any future
 * per-tenant `Webhook` model (see the TODO in `webhook.service.ts`) that a tenant admin could
 * configure through a different endpoint tomorrow. Reuses the exact same literal-IP allow/deny
 * logic as the inbound schema so the two checks cannot silently drift apart.
 * See `.agents/handoffs/onda-1/01-para-05-webhook-worker-ssrf-defense-in-depth.md`.
 */
function isSafeWebhookUrl(url: string): boolean {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return false;
  }
  if (parsed.protocol !== 'https:' && !(parsed.protocol === 'http:' && process.env.NODE_ENV !== 'production')) {
    return false;
  }
  return !isPrivateOrReservedHost(parsed.hostname);
}

/** Thrown when a job carries an `endpointId` that no longer resolves to an active endpoint
 * (deleted or deactivated between enqueue and this delivery attempt) — see signBody below. */
class WebhookEndpointGoneError extends Error {}

/**
 * Signs the exact bytes we are about to send. Receivers recompute this HMAC over the raw request
 * body, so the string signed here and the string sent must be the same one — re-serializing the
 * payload for the request would risk a different key order and a signature that never verifies.
 *
 * Per-tenant endpoints (job carries `endpointId`) sign with that endpoint's own secret, resolved
 * fresh from webhookEndpointService on every attempt — never a single global secret, and never the
 * secret captured at enqueue time (a rotation/deletion mid-retry must take effect immediately, see
 * webhookEndpointService.findActiveSigningSecretHash). Legacy calls with no `endpointId` (a
 * `targetUrl` passed directly to `webhookService.dispatch`, or the deployment-wide
 * WEBHOOK_URL/TEST_WEBHOOK_URL fallback) keep signing with the single deployment-wide
 * WEBHOOK_SIGNING_SECRET env var, exactly as before — no per-tenant endpoint exists to own a
 * secret for that path.
 */
async function signBody(body: string, endpointId?: string): Promise<string | null> {
  if (endpointId) {
    const secretHash = await findActiveSigningSecretHash(endpointId);
    if (!secretHash) {
      throw new WebhookEndpointGoneError(`Webhook endpoint ${endpointId} no longer exists or is inactive`);
    }
    return createHmac('sha256', secretHash).update(body).digest('hex');
  }
  const secret = process.env.WEBHOOK_SIGNING_SECRET;
  if (!secret) return null;
  return createHmac('sha256', secret).update(body).digest('hex');
}

export function startWebhookWorker() {
  const connection = { ...getRedisConnectionOptions(), maxRetriesPerRequest: null };

  const worker = new Worker(
    'webhooks',
    async (job: Job<{ url: string; payload: WebhookPayload; endpointId?: string }>) => {
      const { url, payload, endpointId } = job.data;
      logger.debug(`[WebhookWorker] Processing job ${job.id} for tenant ${payload.organizationId}`);

      if (!isSafeWebhookUrl(url)) {
        // Not a transient delivery failure — the target is categorically disallowed (private/
        // reserved host, cloud metadata address, or a disallowed scheme), so retrying it under
        // the job's backoff config would only waste worker time hammering the same blocked
        // target. UnrecoverableError tells BullMQ to fail the job immediately without consuming
        // the retry budget.
        logger.error(
          `[WebhookWorker] Refusing to deliver event ${payload.type} for tenant ${payload.organizationId} (job ${job.id}): target URL is not an allowed public HTTPS endpoint.`,
        );
        throw new UnrecoverableError('Webhook target URL is not allowed (private/reserved host or disallowed scheme)');
      }

      const body = JSON.stringify(payload);
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
        'User-Agent': 'BirthVoicesHub-Webhook/1.0',
      };

      let signature: string | null;
      try {
        signature = await signBody(body, endpointId);
      } catch (error: any) {
        if (error instanceof WebhookEndpointGoneError) {
          // The endpoint was deleted/deactivated after this job was enqueued — there is no secret
          // left to sign with and no admin left who configured this destination. Same reasoning
          // as the SSRF check above: this is categorically undeliverable, not a transient failure,
          // so fail immediately instead of burning the retry budget against a target that will
          // never become valid again.
          logger.error(`[WebhookWorker] ${error.message} (job ${job.id}) — failing without retry.`);
          throw new UnrecoverableError(error.message);
        }
        throw error;
      }

      if (signature) {
        headers['x-birthvoices-signature'] = signature;
      } else {
        // Without this the receiver cannot tell our requests from anyone else's POST to the same
        // public URL, so it is a deployment error rather than an optional nicety.
        logger.warn('[WebhookWorker] WEBHOOK_SIGNING_SECRET is not set — sending unsigned webhook');
      }

      try {
        const response = await fetch(url, {
          method: 'POST',
          headers,
          body,
          signal: AbortSignal.timeout(DELIVERY_TIMEOUT_MS),
        });

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        logger.info(`[WebhookWorker] Successfully delivered event ${payload.type} to ${url}`);
        if (endpointId) {
          // Best-effort bookkeeping only — must never fail (or slow down) a delivery that already
          // succeeded. This is a real Prisma write against `TenantWebhookEndpoint` (see
          // .agents/handoffs/onda-5/05-para-01-schema-webhook-endpoint-pronto.md); any failure
          // (e.g. the endpoint was deleted between the attempt and this write) is swallowed here
          // for exactly that reason.
          recordDeliveryResult(endpointId, 'delivered').catch(() => undefined);
        }
      } catch (error: unknown) {
        const msg = error instanceof Error ? error.message : String(error);
        logger.error(`[WebhookWorker] Failed to deliver event ${payload.type} to ${url}. Error: ${msg}`);
        throw error; // Let BullMQ handle the retry based on backoff config
      }
    },
    { connection }
  );

  worker.on('failed', (job, err) => {
    logger.error(`[WebhookWorker] Job ${job?.id} failed. Reason: ${err.message}`);
    const endpointId = job?.data?.endpointId;
    const attempts = job?.opts?.attempts ?? 1;
    if (endpointId && job && job.attemptsMade >= attempts) {
      // Final failure (retry budget exhausted) — best-effort bookkeeping, same "never fail on
      // recording" reasoning as the success path above.
      recordDeliveryResult(endpointId, 'failed').catch(() => undefined);
    }
  });

  logger.info('[WebhookWorker] Started listening for webhook events');

  return worker;
}

import type { Prisma } from '@prisma/client';
import type { StudioEdge, StudioNode, ValidationIssue } from '../../lib/studio/types.js';
import * as workflowRepository from '../repositories/workflowRepository.js';
import * as agentRepository from '../repositories/agentRepository.js';
import { logger } from '@/lib/logger';
import {
  knowledgeConfidenceEngine,
  type KnowledgeDocument,
} from '../../lib/voice-runtime/intelligence/KnowledgeConfidenceEngine.js';
import { executeHttpTool } from '../../lib/voice-runtime/HttpToolExecutor.js';
import type { AgentConfiguration } from '../types/agent.js';
import { getAiConsent } from './settingService.js';

export type RuntimeProvider = 'GoogleGemini' | 'OpenAI' | 'Claude';
export type RuntimeNodeType =
  | 'start'
  | 'llm'
  | 'prompt'
  | 'question'
  | 'condition'
  | 'switch'
  | 'memory'
  | 'end'
  | 'knowledge'
  | 'tool'
  | 'voice'
  | 'human_handoff';

type RuntimeConfig = Record<string, Prisma.JsonValue>;

interface RuntimeNode extends Record<string, Prisma.JsonValue> {
  id: string;
  type: RuntimeNodeType;
  config: RuntimeConfig;
}

// Public alias for `RuntimeNode`, exported so a caller resuming an interrupted turn (Agente 05,
// see `resumeAfterTool` below and `.agents/handoffs/onda-6/04-para-05-tool-pending-contrato.md`)
// has a named type to reference without importing the internal `RuntimeNode` name. Structurally
// identical — `state.nodes` (already public on `WorkflowRuntimeState`) is exactly `WorkflowNode[]`.
export type WorkflowNode = RuntimeNode;

interface RuntimeEdge extends Record<string, Prisma.JsonValue> {
  id: string;
  source: string;
  target: string;
  sourceHandle: string | null;
  isFallback: boolean;
  priority: number;
}

/**
 * This snapshot is persisted inside Session.metadata, so its public type deliberately satisfies
 * Prisma.JsonObject. Keeping the runtime state JSON-safe prevents test-only casts from hiding a
 * production persistence mismatch and makes the session snapshot portable across workers.
 *
 * Deliberately NOT extended with new top-level fields for organizationId/agentId/knowledgeDocuments
 * (added in Onda 5 for `knowledge` node support) — every field here must be a required, always
 * JSON-safe (non-`undefined`) value, because `extends Record<string, Prisma.JsonValue>` and an
 * optional property (`foo?: T`, whose type TypeScript always widens to `T | undefined`) cannot
 * coexist on one interface. A genuinely new REQUIRED field is equally unworkable here: both
 * `__tests__/telephonyService.test.ts` and `__tests__/workflowRuntimeService.test.ts` (Agente 08,
 * out of scope for this agent) build `WorkflowRuntimeState`/`Session.metadata` fixtures that
 * predate Onda 5 and do not set it, and TypeScript's spread-of-`Partial<T>` inference makes a
 * required-but-fixture-omitted field surface as `T | undefined` there too. So call-scoped,
 * JSON-safe-but-not-structurally-required data added after the original 9 fields below lives
 * inside the existing required `variables` map instead, under the reserved `__runtime*` keys —
 * see `getRuntimeTenantId`/`getRuntimeAgentId`/`getRuntimeKnowledgeDocuments` further down.
 */
export interface WorkflowRuntimeState extends Record<string, Prisma.JsonValue> {
  workflowId: string;
  version: number;
  currentNodeId: string | null;
  variables: Record<string, string>;
  preferredProvider: RuntimeProvider;
  retries: Record<string, number>;
  ended: boolean;
  nodes: RuntimeNode[];
  edges: RuntimeEdge[];
}

// Reserved `variables` keys carrying call-scoped runtime context (see the `WorkflowRuntimeState`
// doc comment above for why these live inside `variables` instead of as top-level fields). Not
// namespaced against a user typing the literal string in a Studio prompt/condition — an
// astronomically unlikely collision, and even then the leaked value (a tenant id) is not a
// secret — but kept clearly distinguishable from ordinary session variables regardless.
const RUNTIME_TENANT_ID_VAR = '__runtimeTenantId';
const RUNTIME_AGENT_ID_VAR = '__runtimeAgentId';
const RUNTIME_KNOWLEDGE_DOCS_VAR = '__runtimeKnowledgeDocumentsJson';
// Holds the last successfully resolved `voice` node override as it is carried forward across
// turns inside the same JSON-safe `variables` map (see the `WorkflowRuntimeState` doc comment
// above) — same reserved-key pattern as tenant/agent id and knowledge documents.
const RUNTIME_VOICE_OVERRIDE_VAR = '__runtimeVoiceOverrideJson';

function getRuntimeTenantId(state: WorkflowRuntimeState): string {
  return state.variables[RUNTIME_TENANT_ID_VAR] ?? '';
}

function getRuntimeAgentId(state: WorkflowRuntimeState): string | null {
  return state.variables[RUNTIME_AGENT_ID_VAR] || null;
}

function getRuntimeKnowledgeDocuments(state: WorkflowRuntimeState): KnowledgeDocument[] {
  const raw = state.variables[RUNTIME_KNOWLEDGE_DOCS_VAR];
  if (!raw) return [];
  try {
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as KnowledgeDocument[]) : [];
  } catch {
    // A corrupted/hand-edited session snapshot must degrade to "no documents", never throw
    // mid-call — same fail-safe posture as `toStudioGraph` treating a malformed nodes/edges Json
    // column as `[]` in `initializeWorkflowRuntime`.
    return [];
  }
}

function getRuntimeVoiceOverride(state: WorkflowRuntimeState): VoiceOverride | undefined {
  const raw = state.variables[RUNTIME_VOICE_OVERRIDE_VAR];
  if (!raw) return undefined;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (
      parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      && typeof (parsed as Record<string, unknown>).voice === 'string'
      && (parsed as Record<string, unknown>).voice
    ) {
      const language = (parsed as Record<string, unknown>).language;
      return {
        voice: (parsed as { voice: string }).voice,
        ...(typeof language === 'string' && language ? { language } : {}),
      };
    }
    return undefined;
  } catch {
    // Same fail-safe posture as `getRuntimeKnowledgeDocuments`: a corrupted snapshot degrades to
    // "no override" (Twilio's default voice), never a thrown error mid-call.
    return undefined;
  }
}

/**
 * Twilio's own named TTS voice, resolved from the nearest `voice` node the call has passed
 * through (Onda 6 MVP — see the `resolveVoiceOverride` doc comment below for exactly what is and
 * is not honored). Absent whenever no `voice` node has been reached yet, or the configured
 * `provider`/`voiceId` has no known Twilio-native mapping.
 */
export interface VoiceOverride {
  voice: string;
  language?: string;
}

/**
 * MVP transfer target resolved from the nearest `human_handoff` node the call has passed through
 * (Onda 6 rodada 2 — see `resolveTransferDetails` below for exactly what is and is not resolved).
 * `to` is always the node's own literal `fallbackNumber` — this MVP dials that number directly and
 * has no department->number lookup/PBX routing; `department` is carried through purely as a label
 * for logging/observability on the telephony side, never resolved into a phone number itself. See
 * `.agents/handoffs/onda-6/04-para-05-transferDetails-contrato.md`.
 */
export interface TransferDetails {
  to: string;
  timeoutSec: number;
  record: boolean;
  message: string;
  department?: string;
}

export interface PreparedWorkflowTurn {
  state: WorkflowRuntimeState;
  mode: 'llm' | 'direct' | 'tool_pending' | 'transfer';
  systemInstruction?: string;
  preferredProvider?: RuntimeProvider;
  directReply?: string;
  nextQuestion?: string;
  shouldEnd: boolean;
  voiceOverride?: VoiceOverride;
  transferDetails?: TransferDetails;
}

const SUPPORTED_TYPES = new Set<RuntimeNodeType>([
  'start',
  'llm',
  'prompt',
  'question',
  'condition',
  'switch',
  'memory',
  'end',
  'knowledge',
  'tool',
  'voice',
  'human_handoff',
]);

// 'knowledge' and 'tool' were unsupported through Onda 4 (see git history for the removed
// UNSUPPORTED_REASON entries) — as of Onda 5 they are executed for real
// (`applyKnowledgeNode`/`executeToolNodeAsync` below). 'voice' became executable in Onda 6 rodada 1
// as a Twilio-named-TTS MVP (see `resolveVoiceOverride` below and
// `.agents/handoffs/onda-6/04-para-05-voiceOverride-contrato.md`) — it is a passive node that only
// sets `PreparedWorkflowTurn.voiceOverride` and continues to the next node, never an interaction
// by itself. 'human_handoff' became executable in Onda 6 rodada 2
// (`.agents/handoffs/onda-6/00-para-04-human-handoff-mvp.md`): the Studio node already carries a
// literal `fallbackNumber` phone number in its own config (no department->number lookup/schema
// change needed, which was the blocker `.agents/handoffs/onda-5/04-para-05-voice-human-handoff-
// design.md` raised) — see `resolveTransferDetails` below. It is a terminal-of-turn node exactly
// like `prompt`/`question`/`tool`: the synchronous graph walk stops there and
// `PreparedWorkflowTurn.mode` becomes `'transfer'`; unlike `tool`, there is no resume function —
// the runtime has nothing further to execute once a real telephony bridge takes over (Agente 05,
// `telephony.controller.ts`). See docs/patterns/workflow-execution-contract.md §2/§3 for the
// up-to-date executable list. No node type is unsupported by the runtime's capability gate today —
// `UNSUPPORTED_REASON` is kept (empty) as the extension point for the next node type that needs it,
// rather than removed, so `validateRuntimeCompatibility` does not need reshaping again next time.
const UNSUPPORTED_REASON: Partial<Record<string, string>> = {};

const SUPPORTED_TOOL_METHODS = new Set(['GET', 'POST', 'PUT', 'PATCH', 'DELETE']);

function asRecord(value: unknown): RuntimeConfig {
  // Workflow config is persisted in a Prisma Json column before it reaches the runtime. This cast
  // narrows that already-validated JSON boundary; the runtime never accepts arbitrary JS objects
  // directly from request bodies here.
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as RuntimeConfig
    : {};
}

function asString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function asNumber(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function isTruthy(value: unknown): boolean {
  return value === true || (typeof value === 'string' && value.trim().toLowerCase() === 'true');
}

function asOptionalNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function toStudioGraph(nodes: unknown, edges: unknown): { nodes: StudioNode[]; edges: StudioEdge[] } {
  return {
    nodes: Array.isArray(nodes) ? nodes as StudioNode[] : [],
    edges: Array.isArray(edges) ? edges as StudioEdge[] : [],
  };
}

function outgoingFor(edges: StudioEdge[], nodeId: string): StudioEdge[] {
  return edges.filter((edge) => edge.source === nodeId);
}

function branchHandles(edges: StudioEdge[], nodeId: string): Set<string> {
  return new Set(
    outgoingFor(edges, nodeId)
      .map((edge) => edge.sourceHandle)
      .filter((handle): handle is string => typeof handle === 'string' && handle.length > 0),
  );
}

// Twilio's <Say> verb synthesizes speech only from Twilio's own voice catalog — Amazon Polly
// voices under a `Polly.<Name>` identifier, or Google voices under `Google.<name>`
// (https://www.twilio.com/docs/voice/twiml/say#voice). It has no concept of an ElevenLabs voice
// id at all, so a Studio `voice` node's default config (`provider: 'ElevenLabs', voiceId:
// 'Rachel_pt_BR'`) has no honest translation into a Twilio voice name — Option 2 (real
// ElevenLabs synthesis via <Play>) would be needed for that, and is explicitly out of scope for
// this MVP (see .agents/handoffs/onda-6/00-para-04-tool-midcall-voice-upload.md). This table only
// recognizes voice identifiers that ARE ALREADY real, documented Twilio voice names — it never
// guesses "the closest Twilio voice" for an unrelated provider's voice id (AGENTS.md §14: never
// fabricate). Keys are matched case-insensitively, both with and without the `Polly.`/`Google.`
// prefix, against whatever a tenant typed into the Studio inspector's `voiceId` field.
const KNOWN_TWILIO_VOICE_NAMES: Record<string, string> = {
  'polly.camila': 'Polly.Camila',
  'camila': 'Polly.Camila',
  'polly.camila-neural': 'Polly.Camila-Neural',
  'camila-neural': 'Polly.Camila-Neural',
  'polly.vitoria': 'Polly.Vitoria',
  'vitoria': 'Polly.Vitoria',
  'polly.vitória': 'Polly.Vitoria',
  'vitória': 'Polly.Vitoria',
  'polly.ricardo': 'Polly.Ricardo',
  'ricardo': 'Polly.Ricardo',
  'google.pt-br-standard-a': 'Google.pt-BR-Standard-A',
  'pt-br-standard-a': 'Google.pt-BR-Standard-A',
};

// Only a `provider` naming Twilio's own TTS engines is even eligible for the lookup above — this
// is a second, independent guard (not a substitute for the allowlist itself) against an
// accidental short-name collision with an unrelated provider's voice id.
const TWILIO_NATIVE_VOICE_PROVIDERS = new Set(['twilio', 'amazonpolly', 'amazon', 'polly', 'google', 'googletts', 'googlecloudtts']);

/**
 * Resolves a Studio `voice` node's `provider`/`voiceId` into the Twilio-native voice name
 * `PreparedWorkflowTurn.voiceOverride` carries. Only `voiceId` (an already-valid Twilio/Polly/
 * Google voice identifier) and, if present, `language` are honored — `stability`/`clarity`/
 * `speechRate` (ElevenLabs-specific synthesis controls) have no Twilio <Say> equivalent and are
 * silently ignored, never rejected as a validation error (see
 * docs/patterns/workflow-execution-contract.md §3). Returns `undefined` whenever there is no known
 * mapping — the caller must never fall back to guessing a voice name.
 */
function resolveVoiceOverride(config: RuntimeConfig): VoiceOverride | undefined {
  const provider = asString(config.provider).toLowerCase().replace(/[\s_-]+/g, '');
  const voiceId = asString(config.voiceId);
  if (!voiceId || !TWILIO_NATIVE_VOICE_PROVIDERS.has(provider)) return undefined;

  const mapped = KNOWN_TWILIO_VOICE_NAMES[voiceId.toLowerCase()];
  if (!mapped) return undefined;

  const language = asString(config.language);
  return { voice: mapped, ...(language ? { language } : {}) };
}

const DEFAULT_TRANSFER_TIMEOUT_SEC = 30;
const DEFAULT_TRANSFER_MESSAGE = 'Aguarde um momento enquanto encaminho sua ligação.';

/**
 * Resolves a Studio `human_handoff` node's config into the `TransferDetails` Agente 05 dials —
 * MVP: `to` is always the node's own literal `fallbackNumber`, never a department->number lookup
 * (that remains a separate, out-of-scope PBX-routing feature — see
 * `.agents/handoffs/onda-6/04-para-05-transferDetails-contrato.md`). Returns `undefined` whenever
 * `fallbackNumber` is missing/empty — the caller must never invent a destination number.
 */
function resolveTransferDetails(config: RuntimeConfig): TransferDetails | undefined {
  const to = asString(config.fallbackNumber);
  if (!to) return undefined;

  const timeoutSec = asNumber(config.ringTimeoutSec, DEFAULT_TRANSFER_TIMEOUT_SEC);
  const record = isTruthy(config.recordCall);
  const message = asString(config.transferMessage) || DEFAULT_TRANSFER_MESSAGE;
  const department = asString(config.department);

  return { to, timeoutSec, record, message, ...(department ? { department } : {}) };
}

export function mapRuntimeProvider(value: unknown): RuntimeProvider | null {
  const normalized = asString(value).toLowerCase().replace(/[\s_-]+/g, '');
  if (normalized === 'gemini' || normalized === 'googlegemini') return 'GoogleGemini';
  if (normalized === 'openai') return 'OpenAI';
  if (normalized === 'claude' || normalized === 'anthropic') return 'Claude';
  return null;
}

/**
 * Server-side capability gate for the runtime, complementary to ValidationEngine's graph-shape
 * validation. A workflow may be visually valid yet still contain a node that the production
 * telephony executor cannot honestly execute. Those graphs fail closed at publish time instead
 * of being marked active and silently ignored during a real call.
 */
export function validateRuntimeCompatibility(nodes: StudioNode[], edges: StudioEdge[]): ValidationIssue[] {
  const issues: ValidationIssue[] = [];

  for (const node of nodes) {
    const type = node.type;
    if (!type || !SUPPORTED_TYPES.has(type as RuntimeNodeType)) {
      const reason = type ? UNSUPPORTED_REASON[type] : 'O nó não possui um tipo executável.';
      issues.push({
        id: `err-runtime-unsupported-${node.id}`,
        nodeId: node.id,
        type: 'error',
        message: `Este nó ainda não pode ser publicado no runtime de telefonia. ${reason ?? 'Executor de produção indisponível.'}`,
      });
      continue;
    }

    const outgoing = outgoingFor(edges, node.id);
    if (!['condition', 'switch', 'question'].includes(type) && type !== 'end' && outgoing.length > 1) {
      issues.push({
        id: `err-runtime-fanout-${node.id}`,
        nodeId: node.id,
        type: 'error',
        message: 'O runtime exige uma única saída para nós não condicionais; fan-out paralelo ainda não é executado de forma determinística.',
      });
    }

    const config = asRecord(node.data.config);

    if (type === 'llm' && !mapRuntimeProvider(config.provider)) {
      issues.push({
        id: `err-runtime-provider-${node.id}`,
        nodeId: node.id,
        type: 'error',
        message: 'Provedor LLM não suportado pelo runtime. Use Gemini, OpenAI ou Claude.',
      });
    }

    if (type === 'tool') {
      const method = asString(config.method).toUpperCase() || 'GET';
      if (!SUPPORTED_TOOL_METHODS.has(method)) {
        issues.push({
          id: `err-runtime-tool-method-${node.id}`,
          nodeId: node.id,
          type: 'error',
          message: `Método HTTP '${method}' não é suportado pelo executor de Tool. Use GET, POST, PUT, PATCH ou DELETE.`,
        });
      }
    }

    if (type === 'condition') {
      if (isTruthy(config.naturalLanguageCheck)) {
        issues.push({
          id: `err-runtime-nl-condition-${node.id}`,
          nodeId: node.id,
          type: 'error',
          message: 'Condição em linguagem natural ainda não é executável. Use uma variável de sessão e operador determinístico.',
        });
      }

      const operator = asString(config.operator).toLowerCase() || 'equals';
      if (!['equals', 'not_equals', 'contains', 'not_contains', 'exists', 'not_exists', 'regex'].includes(operator)) {
        issues.push({
          id: `err-runtime-condition-operator-${node.id}`,
          nodeId: node.id,
          type: 'error',
          message: `Operador de condição '${operator}' não é suportado pelo runtime.`,
        });
      }

      const handles = branchHandles(edges, node.id);
      if (!handles.has('out-0') || !handles.has('out-1')) {
        issues.push({
          id: `err-runtime-condition-edges-${node.id}`,
          nodeId: node.id,
          type: 'error',
          message: 'Condition precisa conectar out-0 (verdadeiro) e out-1 (falso/fallback).',
        });
      }
    }

    if (type === 'question') {
      const handles = branchHandles(edges, node.id);
      if (!handles.has('out-0') || !handles.has('out-1')) {
        issues.push({
          id: `err-runtime-question-edges-${node.id}`,
          nodeId: node.id,
          type: 'error',
          message: 'Question precisa conectar out-0 (resposta válida) e out-1 (tentativas esgotadas).',
        });
      }

      const validationRegex = asString(config.validationRegex);
      if (validationRegex) {
        try {
          new RegExp(validationRegex, 'i');
        } catch {
          issues.push({
            id: `err-runtime-question-regex-${node.id}`,
            nodeId: node.id,
            type: 'error',
            message: 'A expressão regular configurada na Question é inválida.',
          });
        }
      }
    }

    if (type === 'switch') {
      const outgoingSwitch = outgoingFor(edges, node.id);
      const invalidHandle = outgoingSwitch.find(
        (edge) => !edge.data?.isFallback && !(typeof edge.sourceHandle === 'string' && /^out-\d+$/.test(edge.sourceHandle)),
      );
      if (invalidHandle) {
        issues.push({
          id: `err-runtime-switch-edge-${invalidHandle.id}`,
          nodeId: node.id,
          edgeId: invalidHandle.id,
          type: 'error',
          message: 'Cada saída do Switch precisa usar um sourceHandle out-N ou ser marcada explicitamente como fallback.',
        });
      }
    }
  }

  return issues;
}

function compileNodes(nodes: StudioNode[]): RuntimeNode[] {
  return nodes
    .filter((node): node is StudioNode & { type: RuntimeNodeType } => Boolean(node.type && SUPPORTED_TYPES.has(node.type as RuntimeNodeType)))
    .map((node) => ({ id: node.id, type: node.type, config: asRecord(node.data.config) }));
}

function compileEdges(edges: StudioEdge[]): RuntimeEdge[] {
  return edges.map((edge) => ({
    id: edge.id,
    source: edge.source,
    target: edge.target,
    sourceHandle: typeof edge.sourceHandle === 'string' ? edge.sourceHandle : null,
    isFallback: edge.data?.isFallback === true,
    priority: typeof edge.data?.priority === 'number' ? edge.data.priority : 0,
  }));
}

function nodeById(state: WorkflowRuntimeState, nodeId: string | null): RuntimeNode | null {
  if (!nodeId) return null;
  return state.nodes.find((node) => node.id === nodeId) ?? null;
}

function orderedOutgoing(state: WorkflowRuntimeState, nodeId: string): RuntimeEdge[] {
  return state.edges
    .filter((edge) => edge.source === nodeId)
    .sort((a, b) => b.priority - a.priority || a.id.localeCompare(b.id));
}

function selectHandle(state: WorkflowRuntimeState, nodeId: string, handle: string): RuntimeEdge | null {
  const outgoing = orderedOutgoing(state, nodeId);
  return outgoing.find((edge) => edge.sourceHandle === handle)
    ?? outgoing.find((edge) => edge.isFallback)
    ?? null;
}

function selectDefaultEdge(state: WorkflowRuntimeState, nodeId: string): RuntimeEdge | null {
  return orderedOutgoing(state, nodeId)[0] ?? null;
}

function renderTemplate(template: string, variables: Record<string, string>): string {
  return template.replace(/\{\{\s*([\w.-]+)\s*\}\}/g, (_match, key: string) => variables[key] ?? '');
}

function normalizeComparable(value: string): string {
  return value.trim().toLocaleLowerCase('pt-BR');
}

function evaluateCondition(config: RuntimeConfig, variables: Record<string, string>): boolean {
  const variable = asString(config.variable);
  const operator = asString(config.operator).toLowerCase() || 'equals';
  const actual = variables[variable] ?? '';
  const expected = renderTemplate(asString(config.value), variables);
  const a = normalizeComparable(actual);
  const b = normalizeComparable(expected);

  switch (operator) {
    case 'equals': return a === b;
    case 'not_equals': return a !== b;
    case 'contains': return a.includes(b);
    case 'not_contains': return !a.includes(b);
    case 'exists': return actual.trim().length > 0;
    case 'not_exists': return actual.trim().length === 0;
    case 'regex': {
      try {
        return new RegExp(expected, 'i').test(actual);
      } catch {
        return false;
      }
    }
    default: return false;
  }
}

function applyMemoryNode(config: RuntimeConfig, variables: Record<string, string>): void {
  const operation = asString(config.operation).toLowerCase();
  const variableName = asString(config.variableName);

  if (operation === 'reset' || operation === 'reset session') {
    for (const key of Object.keys(variables)) delete variables[key];
    return;
  }

  if (!variableName) return;

  if (operation === 'delete variable' || operation === 'remove variable' || operation === 'delete') {
    delete variables[variableName];
    return;
  }

  variables[variableName] = renderTemplate(asString(config.variableValue), variables);
}

function routeSwitch(state: WorkflowRuntimeState, node: RuntimeNode): RuntimeEdge | null {
  const variableName = asString(node.config.variableToCheck);
  const actual = normalizeComparable(state.variables[variableName] ?? '');
  const paths = Object.entries(node.config)
    .map(([key, value]) => {
      const match = /^path(\d+)$/.exec(key);
      return match ? { index: Number(match[1]), value: asString(value) } : null;
    })
    .filter((entry): entry is { index: number; value: string } => entry !== null)
    .sort((a, b) => a.index - b.index);

  const matched = paths.find((entry) => normalizeComparable(entry.value) === actual);
  if (matched) return selectHandle(state, node.id, `out-${matched.index}`);

  return orderedOutgoing(state, node.id).find((edge) => edge.isFallback) ?? null;
}

/**
 * `evaluateKnowledge` is a keyword-confidence lookup over whatever documents were baked into the
 * state snapshot at call start, NOT a real vector/embeddings search — see
 * `KnowledgeConfidenceEngine.ts`'s own "RAG Simulator" comment and
 * `docs/patterns/workflow-execution-contract.md` §2. This function must never present a
 * low-confidence/no-match result as a fact (AGENTS.md §14) and must never invent a result for a
 * `database` name that matches no configured document.
 *
 * The query is always the caller's most recent utterance (`variables.lastUserText`) — the Studio
 * config table for `knowledge` (`ragTopK`, `minScoreThreshold`, `searchStrategy`,
 * `autoChunkSize`) has no field to pick a different query source today. `ragTopK`/
 * `searchStrategy`/`autoChunkSize` are accepted by the Studio schema but are NOT honored here:
 * the engine returns a single best match, not a ranked top-K over chunked documents. Only
 * `minScoreThreshold` is honored, as an additional (never looser) floor on top of the engine's
 * own fixed threshold.
 */
function applyKnowledgeNode(state: WorkflowRuntimeState, node: RuntimeNode): void {
  const query = state.variables.lastUserText ?? '';
  const requestedDatabase = asString(node.config.database);
  const documents = getRuntimeKnowledgeDocuments(state);
  const pool = requestedDatabase
    ? documents.filter((doc) => normalizeComparable(doc.name) === normalizeComparable(requestedDatabase))
    : documents;

  const result = knowledgeConfidenceEngine.evaluateKnowledge(query, pool);
  const minScoreThreshold = asNumber(node.config.minScoreThreshold, 0);
  const isLowConfidence = result.isLowConfidence || result.confidence < minScoreThreshold;

  // Fixed variable names (no `variableToSave` field exists for `knowledge` in the Studio config
  // table) — a downstream `prompt`/`question`/`condition` node reads these via the existing
  // `{{variable}}` template mechanism (see renderTemplate). Both a generic "most recent lookup"
  // set and a per-node-id set are written so multiple knowledge nodes in one graph don't clobber
  // each other's result.
  state.variables.knowledge_result = result.snippetUsed;
  state.variables.knowledge_document = result.document;
  state.variables.knowledge_confidence = String(result.confidence);
  state.variables.knowledge_is_low_confidence = String(isLowConfidence);
  state.variables[`knowledge_${node.id}_result`] = result.snippetUsed;
  state.variables[`knowledge_${node.id}_is_low_confidence`] = String(isLowConfidence);
}

// The Studio's `tool` node registry persists `headers` as a JSON-encoded string in
// `data.config.headers` (see `store/useStudioStore.ts`'s `tool` node `defaultConfig`, e.g.
// `'{"Authorization": "Bearer token_secret"}'`) — every workflow published through the Inspector
// carries it that way, never as a live object. Parsing it here (instead of requiring an object) is
// what actually makes a configured header like `Authorization` reach the request; accepting an
// object too keeps this tolerant of a future Studio change without another silent breakage.
function toToolHeaders(value: unknown, variables: Record<string, string>): Record<string, string> {
  let parsed: unknown = value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return {};
    try {
      parsed = JSON.parse(trimmed);
    } catch {
      return {};
    }
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
  const headers: Record<string, string> = {};
  for (const [key, raw] of Object.entries(parsed as Record<string, unknown>)) {
    if (typeof raw === 'string') headers[key] = renderTemplate(raw, variables);
  }
  return headers;
}

/**
 * `tool` failure fallback — applied whenever a real HTTP attempt (`executeToolNodeAsync`) did not
 * end in `result.ok`, regardless of which entry point drove it (call-start's
 * `advanceUntilInteractionAsync`, or a mid-call `resumeAfterTool`). Never a fabricated success,
 * never an unhandled exception up into `telephonyService.ts`.
 *
 * Onda 6 history: through Onda 5, a `tool` node reached mid-conversation (via the synchronous
 * `prepareWorkflowTurn`) could not perform a real network call at all — the synchronous path had
 * no way to `await` one — so it degraded straight to this fallback without ever calling the
 * configured endpoint. As of Onda 6, `advanceUntilInteraction` (sync) instead stops the graph at a
 * `tool` node (`mode: 'tool_pending'`, see `PreparedWorkflowTurn`) and the real call happens in
 * `resumeAfterTool` below — this function is now reached only on a genuine failure (timeout,
 * blocked URL, non-2xx, consent not granted), never merely because the call was reached
 * mid-conversation. See `.agents/handoffs/onda-6/04-para-05-tool-pending-contrato.md`.
 */
function applyToolFallback(state: WorkflowRuntimeState, node: RuntimeNode, reason: string): void {
  state.variables.tool_ok = 'false';
  state.variables.tool_status = reason;
  state.variables.tool_error = reason;
  state.variables.tool_result = undefined;
  state.variables[`tool_${node.id}_ok`] = 'false';
  state.variables[`tool_${node.id}_error`] = reason;
}

/**
 * Real execution path for a `tool` node — called from `advanceUntilInteractionAsync` (before the
 * call's first `prompt`/`question`) and, as of Onda 6, from `resumeAfterTool` (a `tool` node
 * reached later, mid-conversation). SSRF/timeout/retry defense lives in `executeHttpTool`
 * (`lib/voice-runtime/HttpToolExecutor.ts`), reusing `isPrivateOrReservedHost` from
 * `src/validators/index.ts` — never re-implemented here.
 *
 * Gated on the same tenant-level external-data-egress consent already required for AI providers
 * (`getAiConsent`, AGENTS.md §16) before the call fires: a `tool` node sends caller/lead fields
 * (`{{from}}`, `{{to}}`, workflow variables) to a tenant-configured URL, an external destination
 * for personal data exactly like the AI Gateway's, and today the only consent primitive this
 * platform has is that one — reusing it here is a real check now rather than none while a
 * dedicated "tool endpoint" consent flag is decided as a separate product change. Checked fresh on
 * every call (never cached in the immutable per-call state), fail-closed on the lookup itself
 * erroring (mirrors `requireAiProviderConsent`'s middleware, which returns 503 rather than
 * treating a DB error as "no consent") — never fabricate consent, never let an outage silently
 * downgrade to "allowed".
 */
async function executeToolNodeAsync(state: WorkflowRuntimeState, node: RuntimeNode): Promise<void> {
  const organizationId = getRuntimeTenantId(state);
  try {
    const consent = await getAiConsent(organizationId);
    if (!consent.granted) {
      logger.warn('Workflow tool node blocked: tenant has not granted external data consent', {
        workflowId: state.workflowId,
        organizationId,
        nodeId: node.id,
      });
      applyToolFallback(state, node, 'consent_not_granted');
      return;
    }
  } catch (error: any) {
    logger.error('Failed to verify tenant consent before executing workflow tool node', {
      workflowId: state.workflowId,
      organizationId,
      nodeId: node.id,
      error: error instanceof Error ? error.message : String(error),
    });
    applyToolFallback(state, node, 'consent_check_unavailable');
    return;
  }

  const endpoint = renderTemplate(asString(node.config.endpoint), state.variables);
  const bodyPayload = typeof node.config.bodyPayload === 'string'
    ? renderTemplate(node.config.bodyPayload, state.variables)
    : node.config.bodyPayload;

  const result = await executeHttpTool({
    method: asString(node.config.method) || 'GET',
    endpoint,
    headers: toToolHeaders(node.config.headers, state.variables),
    bodyPayload,
    timeoutMs: asOptionalNumber(node.config.timeoutMs),
    retryLimit: asOptionalNumber(node.config.retryLimit),
  });

  if (result.ok) {
    state.variables.tool_ok = 'true';
    state.variables.tool_status = String(result.status ?? '');
    state.variables.tool_result = result.body ?? '';
    state.variables.tool_error = undefined;
    state.variables[`tool_${node.id}_ok`] = 'true';
    state.variables[`tool_${node.id}_result`] = result.body ?? '';
    logger.info('Workflow tool node executed successfully', {
      workflowId: state.workflowId,
      organizationId: getRuntimeTenantId(state),
      agentId: getRuntimeAgentId(state),
      nodeId: node.id,
      status: result.status,
    });
    return;
  }

  logger.warn('Workflow tool node failed; continuing the call on the fallback path', {
    workflowId: state.workflowId,
    organizationId: getRuntimeTenantId(state),
    agentId: getRuntimeAgentId(state),
    nodeId: node.id,
    reason: result.error,
  });
  applyToolFallback(state, node, result.error ?? 'unknown_error');
}

async function loadAgentKnowledgeDocuments(organizationId: string, agentId: string): Promise<KnowledgeDocument[]> {
  try {
    // Tenant-scoped lookup: `agentRepository.getAgent` only returns a row when `agentId` actually
    // belongs to `organizationId`, so a mismatched/foreign agentId yields no documents rather than
    // another tenant's knowledge base — this is the tenant-isolation guarantee for `knowledge`.
    const agent = await agentRepository.getAgent(agentId, organizationId);
    if (!agent) return [];
    const config = (agent.configuration as unknown as AgentConfiguration) || {};
    return Array.isArray(config.knowledge) ? config.knowledge : [];
  } catch (error: any) {
    logger.error('Failed to load agent knowledge documents for workflow runtime', {
      organizationId,
      agentId,
      error: error instanceof Error ? error.message : String(error),
    });
    return [];
  }
}

/**
 * Executes every node type that has no I/O side effect requiring `await` — shared by both
 * `advanceUntilInteraction` (sync, every phone turn) and `advanceUntilInteractionAsync` (async,
 * call start only) so `condition`/`switch`/`memory`/`llm`/`knowledge` semantics can never drift
 * between the two entry points. Returns the id of the next node to visit, or `null` to stop.
 * Caller has already handled `prompt`/`question`/`end`/`tool` before reaching this function.
 */
function advanceDeterministicNode(state: WorkflowRuntimeState, node: RuntimeNode): string | null {
  if (node.type === 'llm') {
    const provider = mapRuntimeProvider(node.config.provider);
    if (provider) state.preferredProvider = provider;
    return selectDefaultEdge(state, node.id)?.target ?? null;
  }

  if (node.type === 'memory') {
    applyMemoryNode(node.config, state.variables);
    return selectDefaultEdge(state, node.id)?.target ?? null;
  }

  if (node.type === 'condition') {
    const matched = evaluateCondition(node.config, state.variables);
    return selectHandle(state, node.id, matched ? 'out-0' : 'out-1')?.target ?? null;
  }

  if (node.type === 'switch') {
    return routeSwitch(state, node)?.target ?? null;
  }

  if (node.type === 'knowledge') {
    applyKnowledgeNode(state, node);
    return selectDefaultEdge(state, node.id)?.target ?? null;
  }

  if (node.type === 'voice') {
    // Passive node: it never interacts with the caller by itself, only (re)sets the active
    // Twilio voice override for whatever interaction comes next — see `resolveVoiceOverride`.
    // Reaching a `voice` node with no known mapping clears any earlier override rather than
    // leaving a stale one from a previous `voice` node in the same call.
    const override = resolveVoiceOverride(node.config);
    if (override) {
      state.variables[RUNTIME_VOICE_OVERRIDE_VAR] = JSON.stringify(override);
    } else {
      delete state.variables[RUNTIME_VOICE_OVERRIDE_VAR];
    }
    return selectDefaultEdge(state, node.id)?.target ?? null;
  }

  return selectDefaultEdge(state, node.id)?.target ?? null;
}

function hasResolvableTransfer(node: RuntimeNode): boolean {
  return resolveTransferDetails(node.config) !== undefined;
}

/**
 * Shared by both graph walkers (`advanceUntilInteraction`/`advanceUntilInteractionAsync`): a
 * `human_handoff` node reached with no configured `fallbackNumber` is never a stopping point —
 * AGENTS.md §14 forbids fabricating a transfer destination, so this treats it exactly like a
 * failed `tool` node (see `applyToolFallback`): log a warning, leave a recoverable
 * `handoff_ok`/`handoff_error` pair for a downstream `condition` node, and continue the walk past
 * it on its single outgoing edge (or stop the call if it has none). Never invents a phone number.
 */
function skipUnresolvableHumanHandoff(state: WorkflowRuntimeState, node: RuntimeNode): string | null {
  logger.warn('Workflow human_handoff node has no fallbackNumber configured; skipping the transfer and continuing on the default path', {
    workflowId: state.workflowId,
    nodeId: node.id,
  });
  state.variables.handoff_ok = 'false';
  state.variables.handoff_error = 'fallback_number_missing';
  state.variables[`handoff_${node.id}_ok`] = 'false';
  state.variables[`handoff_${node.id}_error`] = 'fallback_number_missing';
  return selectDefaultEdge(state, node.id)?.target ?? null;
}

/**
 * Synchronous graph walk used by every `prepareWorkflowTurn` call (a live phone turn,
 * `telephonyService.ts` calling it without `await`). As of Onda 6, a `tool` node is a stopping
 * point exactly like `prompt`/`question`/`end`: it cannot perform a real network call from inside
 * this synchronous function (that would either break the non-`await`ed call site or block the
 * event loop for every other concurrent call), so it leaves `currentNodeId` pointed at the `tool`
 * node itself and returns — `prepareWorkflowTurn` turns that into `mode: 'tool_pending'` and the
 * caller must resume with `resumeAfterTool` (below), which performs the real HTTP call and then
 * continues the walk from there. See `.agents/handoffs/onda-6/04-para-05-tool-pending-contrato.md`.
 */
function advanceUntilInteraction(state: WorkflowRuntimeState, fromNodeId: string | null): WorkflowRuntimeState {
  let currentId = fromNodeId;
  const visited = new Set<string>();

  while (currentId) {
    if (visited.has(currentId)) {
      state.ended = true;
      state.currentNodeId = null;
      logger.error('Workflow runtime stopped an unexpected cycle', { workflowId: state.workflowId, nodeId: currentId });
      return state;
    }
    visited.add(currentId);

    const node = nodeById(state, currentId);
    if (!node) {
      state.ended = true;
      state.currentNodeId = null;
      logger.error('Workflow runtime could not resolve node', { workflowId: state.workflowId, nodeId: currentId });
      return state;
    }

    if (node.type === 'human_handoff') {
      if (hasResolvableTransfer(node)) {
        state.currentNodeId = node.id;
        return state;
      }
      currentId = skipUnresolvableHumanHandoff(state, node);
      continue;
    }

    if (node.type === 'prompt' || node.type === 'question' || node.type === 'tool') {
      state.currentNodeId = node.id;
      return state;
    }

    if (node.type === 'end') {
      state.ended = true;
      state.currentNodeId = node.id;
      return state;
    }

    currentId = advanceDeterministicNode(state, node);
  }

  state.ended = true;
  state.currentNodeId = null;
  return state;
}

/**
 * Async twin of `advanceUntilInteraction`, used only by `initializeWorkflowRuntime` (i.e. the
 * segment of the graph between `start` and the call's first `prompt`/`question`). A `tool` node
 * reached here performs a real HTTP call inline (`executeToolNodeAsync`) because this function is
 * already `await`ed by its only caller; a `tool` node reached later, mid-conversation, instead
 * goes through `advanceUntilInteraction` (sync) + `resumeAfterTool` — see that pair's doc
 * comments for why the two entry points cannot share one code path.
 */
async function advanceUntilInteractionAsync(state: WorkflowRuntimeState, fromNodeId: string | null): Promise<WorkflowRuntimeState> {
  let currentId = fromNodeId;
  const visited = new Set<string>();

  while (currentId) {
    if (visited.has(currentId)) {
      state.ended = true;
      state.currentNodeId = null;
      logger.error('Workflow runtime stopped an unexpected cycle', { workflowId: state.workflowId, nodeId: currentId });
      return state;
    }
    visited.add(currentId);

    const node = nodeById(state, currentId);
    if (!node) {
      state.ended = true;
      state.currentNodeId = null;
      logger.error('Workflow runtime could not resolve node', { workflowId: state.workflowId, nodeId: currentId });
      return state;
    }

    if (node.type === 'prompt' || node.type === 'question') {
      state.currentNodeId = node.id;
      return state;
    }

    if (node.type === 'end') {
      state.ended = true;
      state.currentNodeId = node.id;
      return state;
    }

    if (node.type === 'human_handoff') {
      // Known limitation, same shape as the `voice` node's opening-greeting gap documented in
      // `.agents/handoffs/onda-6/04-para-05-voiceOverride-contrato.md`: `initializeWorkflowRuntime`
      // returns a bare `WorkflowRuntimeState`, not a `PreparedWorkflowTurn`, so a `human_handoff`
      // reached in this initial segment (before the call's first `prompt`/`question`) stops the
      // walk here (never fabricates a transfer, never silently drops it) but has no channel to
      // surface `mode: 'transfer'` to a caller yet. `currentNodeId` stays correctly pointed at it,
      // so the very next `prepareWorkflowTurn` call re-signals `mode: 'transfer'` via the same
      // defensive re-check `advanceUntilInteraction` relies on for `tool`.
      if (hasResolvableTransfer(node)) {
        state.currentNodeId = node.id;
        return state;
      }
      currentId = skipUnresolvableHumanHandoff(state, node);
      continue;
    }

    if (node.type === 'tool') {
      await executeToolNodeAsync(state, node);
      currentId = selectDefaultEdge(state, node.id)?.target ?? null;
      continue;
    }

    currentId = advanceDeterministicNode(state, node);
  }

  state.ended = true;
  state.currentNodeId = null;
  return state;
}

function cloneState(state: WorkflowRuntimeState): WorkflowRuntimeState {
  return structuredClone(state);
}

function advancePastCurrent(state: WorkflowRuntimeState, current: RuntimeNode, handle?: string): WorkflowRuntimeState {
  const edge = handle ? selectHandle(state, current.id, handle) : selectDefaultEdge(state, current.id);
  return advanceUntilInteraction(state, edge?.target ?? null);
}

function questionText(state: WorkflowRuntimeState): string | undefined {
  const current = nodeById(state, state.currentNodeId);
  if (current?.type !== 'question') return undefined;
  const text = renderTemplate(asString(current.config.questionText), state.variables);
  return text || undefined;
}

function closingMessage(state: WorkflowRuntimeState): string {
  const current = nodeById(state, state.currentNodeId);
  const configured = current?.type === 'end' ? asString(current.config.closingMessage) : '';
  return configured || 'Obrigado pelo contato. Até logo.';
}

export async function initializeWorkflowRuntime(
  organizationId: string,
  initialVariables: Record<string, unknown> = {},
  // Optional today because `telephonyService.ts` (Agente 05) does not pass it yet at its two
  // call sites (`startCall`/`startOutboundCall`, both of which already have the resolved `Agent`
  // in scope) — see .agents/handoffs/onda-5/04-para-05-pass-agentid-to-workflow-runtime.md.
  // Without it, `knowledge` nodes execute honestly with zero documents (never a fabricated
  // match) instead of failing; adding the argument is additive and does not change any existing
  // caller's behavior.
  agentId?: string,
): Promise<WorkflowRuntimeState | null> {
  const workflow = await workflowRepository.findActiveWorkflowForTenant(organizationId);
  if (!workflow) return null;

  const { nodes, edges } = toStudioGraph(workflow.nodes, workflow.edges);
  const runtimeIssues = validateRuntimeCompatibility(nodes, edges);
  if (runtimeIssues.length > 0) {
    logger.error('Active workflow is not runtime-compatible; refusing to execute it', {
      organizationId,
      workflowId: workflow.id,
      issueIds: runtimeIssues.map((issue) => issue.id),
    });
    return null;
  }

  const start = nodes.find((node) => node.type === 'start');
  if (!start) return null;

  const knowledgeDocuments = agentId ? await loadAgentKnowledgeDocuments(organizationId, agentId) : [];

  const state: WorkflowRuntimeState = {
    workflowId: workflow.id,
    version: workflow.version,
    currentNodeId: start.id,
    variables: {
      ...Object.fromEntries(
        Object.entries(initialVariables)
          .filter(([, value]) => value !== null && value !== undefined)
          .map(([key, value]) => [key, String(value)]),
      ),
      [RUNTIME_TENANT_ID_VAR]: organizationId,
      ...(agentId ? { [RUNTIME_AGENT_ID_VAR]: agentId } : {}),
      [RUNTIME_KNOWLEDGE_DOCS_VAR]: JSON.stringify(knowledgeDocuments),
    },
    preferredProvider: 'GoogleGemini',
    retries: {},
    ended: false,
    nodes: compileNodes(nodes),
    edges: compileEdges(edges),
  };

  return advanceUntilInteractionAsync(state, start.id);
}

export function getWorkflowOpeningQuestion(state: WorkflowRuntimeState | null): string | null {
  if (!state || state.ended) return null;
  return questionText(state) ?? null;
}

// Single attachment point for `voiceOverride` on every `PreparedWorkflowTurn` this module
// returns (`prepareWorkflowTurn` and `resumeAfterTool`), so no individual `return` inside either
// function has to remember to carry it — see `resolveVoiceOverride`/`getRuntimeVoiceOverride`
// above for what is and is not resolvable.
function attachVoiceOverride(turn: PreparedWorkflowTurn): PreparedWorkflowTurn {
  const voiceOverride = getRuntimeVoiceOverride(turn.state);
  return voiceOverride ? { ...turn, voiceOverride } : turn;
}

/**
 * Checks whether the graph walk just stopped at a node that itself demands a special
 * `PreparedWorkflowTurn.mode` instead of the ordinary `llm`/`direct` result the caller was
 * building — a `tool` node (`tool_pending`, resumed via `resumeAfterTool`) or a `human_handoff`
 * node with a resolvable transfer (`transfer`, terminal — no resume function exists for it).
 * Returns `null` when neither applies, so the caller falls through to its normal `llm`/`direct`
 * logic unchanged. Centralizing this (instead of re-deriving it after every `advancePastCurrent`
 * call, as the pre-Onda-6-rodada-2 `isToolPending` helper required its callers to do individually)
 * is what guarantees a `human_handoff` reached right after a `tool`/`question`/`prompt` node is
 * never silently missed at any of the call sites below.
 */
function pendingInterruptTurn(state: WorkflowRuntimeState): PreparedWorkflowTurn | null {
  const node = nodeById(state, state.currentNodeId);
  if (!node) return null;

  if (node.type === 'tool') {
    return { state, mode: 'tool_pending', shouldEnd: false };
  }

  if (node.type === 'human_handoff') {
    const transferDetails = resolveTransferDetails(node.config);
    if (transferDetails) {
      return { state, mode: 'transfer', transferDetails, shouldEnd: false };
    }
  }

  return null;
}

export function prepareWorkflowTurn(state: WorkflowRuntimeState, userText: string): PreparedWorkflowTurn {
  return attachVoiceOverride(prepareWorkflowTurnInternal(state, userText));
}

function prepareWorkflowTurnInternal(state: WorkflowRuntimeState, userText: string): PreparedWorkflowTurn {
  const next = cloneState(state);
  next.variables.lastUserText = userText;

  if (next.ended) {
    return { state: next, mode: 'direct', directReply: closingMessage(next), shouldEnd: true };
  }

  const current = nodeById(next, next.currentNodeId);
  if (!current) {
    next.ended = true;
    return { state: next, mode: 'direct', directReply: closingMessage(next), shouldEnd: true };
  }

  // Defensive only: a correct caller never calls `prepareWorkflowTurn` again while the previous
  // turn's `mode` was `'tool_pending'`/`'transfer'` — it calls `resumeAfterTool` for the former
  // (see `.agents/handoffs/onda-6/04-para-05-tool-pending-contrato.md`), and there is nothing to
  // resume for the latter (`human_handoff` has no resume function — see
  // `.agents/handoffs/onda-6/04-para-05-transferDetails-contrato.md`). If a caller re-invokes this
  // anyway while still parked on either node, re-signal the same mode rather than silently
  // treating the node as a generic dead end.
  const pendingAtCurrent = pendingInterruptTurn(next);
  if (pendingAtCurrent) return pendingAtCurrent;

  if (current.type === 'question') {
    const regexText = asString(current.config.validationRegex);
    let valid = true;
    if (regexText) {
      try {
        valid = new RegExp(regexText, 'i').test(userText);
      } catch {
        valid = false;
      }
    }

    if (!valid) {
      const attempts = (next.retries[current.id] ?? 0) + 1;
      next.retries[current.id] = attempts;
      const maxRetryCount = Math.max(0, asNumber(current.config.maxRetryCount, 3));
      const fallbackPrompt = renderTemplate(
        asString(current.config.fallbackPrompt) || asString(current.config.questionText) || 'Não entendi. Pode repetir?',
        next.variables,
      );

      if (attempts <= maxRetryCount) {
        return { state: next, mode: 'direct', directReply: fallbackPrompt, shouldEnd: false };
      }

      delete next.retries[current.id];
      advancePastCurrent(next, current, 'out-1');
      const pendingAfterRetriesExhausted = pendingInterruptTurn(next);
      if (pendingAfterRetriesExhausted) return pendingAfterRetriesExhausted;
      const nextQuestion = questionText(next);
      return {
        state: next,
        mode: 'direct',
        directReply: [fallbackPrompt, nextQuestion].filter(Boolean).join(' '),
        shouldEnd: next.ended,
      };
    }

    const variableToSave = asString(current.config.variableToSave);
    if (variableToSave) next.variables[variableToSave] = userText;
    delete next.retries[current.id];
    advancePastCurrent(next, current, 'out-0');

    const pendingAfterAnswer = pendingInterruptTurn(next);
    if (pendingAfterAnswer) return pendingAfterAnswer;

    const afterQuestion = nodeById(next, next.currentNodeId);
    if (afterQuestion?.type === 'prompt') {
      const instruction = renderTemplate(asString(afterQuestion.config.promptText), next.variables);
      advancePastCurrent(next, afterQuestion);
      const pendingAfterPrompt = pendingInterruptTurn(next);
      if (pendingAfterPrompt) return pendingAfterPrompt;
      return {
        state: next,
        mode: 'llm',
        systemInstruction: instruction,
        preferredProvider: next.preferredProvider,
        nextQuestion: questionText(next),
        shouldEnd: next.ended,
      };
    }

    const nextQuestion = questionText(next);
    return {
      state: next,
      mode: 'direct',
      directReply: nextQuestion ?? (next.ended ? closingMessage(next) : 'Obrigado. Pode continuar.'),
      shouldEnd: next.ended,
    };
  }

  if (current.type === 'prompt') {
    const instruction = renderTemplate(asString(current.config.promptText), next.variables);
    advancePastCurrent(next, current);
    const pendingAfterPrompt = pendingInterruptTurn(next);
    if (pendingAfterPrompt) return pendingAfterPrompt;
    return {
      state: next,
      mode: 'llm',
      systemInstruction: instruction,
      preferredProvider: next.preferredProvider,
      nextQuestion: questionText(next),
      shouldEnd: next.ended,
    };
  }

  next.ended = true;
  return { state: next, mode: 'direct', directReply: closingMessage(next), shouldEnd: true };
}

/**
 * Resumes a call that `prepareWorkflowTurn` paused with `mode: 'tool_pending'` — the async
 * continuation promised in `.agents/handoffs/onda-6/04-para-05-tool-pending-contrato.md`. `node`
 * must be the pending `tool` node (`state.nodes.find((n) => n.id === state.currentNodeId)`, or
 * whatever reference the caller already holds from the turn that returned `tool_pending`); if it
 * does not match a `tool` node actually at `state.currentNodeId`, this degrades to ending the call
 * rather than guessing at a graph position, exactly like `prepareWorkflowTurn` does for any other
 * unresolvable/corrupted state.
 *
 * Performs the real HTTP call (`executeToolNodeAsync`, reusing the same consent gate and
 * `HttpToolExecutor` SSRF/timeout/retry defense already used at call start), then continues
 * walking the graph exactly like `prepareWorkflowTurn` would — including returning another
 * `tool_pending` if a second `tool` node follows immediately, or `tool_ok='false'`/`tool_error`
 * on the same fallback path a live call-start failure already takes (`applyToolFallback`) — never
 * a fabricated success and never an unhandled exception back into `telephonyService.ts`.
 */
export async function resumeAfterTool(state: WorkflowRuntimeState, node: WorkflowNode): Promise<PreparedWorkflowTurn> {
  const next = cloneState(state);
  const toolNode = nodeById(next, node.id);

  if (toolNode?.type !== 'tool') {
    logger.error('resumeAfterTool called without a matching pending tool node', {
      workflowId: next.workflowId,
      nodeId: node.id,
    });
    next.ended = true;
    return attachVoiceOverride({ state: next, mode: 'direct', directReply: closingMessage(next), shouldEnd: true });
  }

  await executeToolNodeAsync(next, toolNode);
  advancePastCurrent(next, toolNode);

  const pendingAfterTool = pendingInterruptTurn(next);
  if (pendingAfterTool) return attachVoiceOverride(pendingAfterTool);

  const current = nodeById(next, next.currentNodeId);

  if (current?.type === 'prompt') {
    const instruction = renderTemplate(asString(current.config.promptText), next.variables);
    advancePastCurrent(next, current);
    const pendingAfterPrompt = pendingInterruptTurn(next);
    if (pendingAfterPrompt) return attachVoiceOverride(pendingAfterPrompt);
    return attachVoiceOverride({
      state: next,
      mode: 'llm',
      systemInstruction: instruction,
      preferredProvider: next.preferredProvider,
      nextQuestion: questionText(next),
      shouldEnd: next.ended,
    });
  }

  if (current?.type === 'question') {
    return attachVoiceOverride({
      state: next,
      mode: 'direct',
      directReply: questionText(next) ?? (next.ended ? closingMessage(next) : 'Obrigado. Pode continuar.'),
      shouldEnd: next.ended,
    });
  }

  return attachVoiceOverride({ state: next, mode: 'direct', directReply: closingMessage(next), shouldEnd: true });
}

import * as workflowRepository from '../repositories/workflowRepository.js';
import { validationEngine } from '../../studio/ValidationEngine.js';
import { validateRuntimeCompatibility } from './workflowRuntimeService.js';
import { logger } from '@/lib/logger';
import type { StudioNode, StudioEdge, ValidationIssue } from '../../lib/studio/types.js';

export class NotFoundError extends Error {}

/**
 * Thrown by `publishWorkflow` when the workflow's nodes/edges don't pass the visual graph
 * validator or the production-runtime capability gate. This is the ONLY error type an
 * "activate/publish" caller should ever see for a rejected workflow — there is no other
 * successful code path that marks a workflow `status: 'active'`.
 */
export class ValidationFailedError extends Error {
  issues: ValidationIssue[];
  constructor(issues: ValidationIssue[]) {
    super('O fluxo contém erros de validação e não pode ser publicado/ativado.');
    this.name = 'ValidationFailedError';
    this.issues = issues;
  }
}

/**
 * `Workflow.nodes`/`edges` are persisted as Prisma `Json` (see prisma/schema.prisma), so at the
 * type level they're `unknown` until read back. Studio is the only normal writer of that column,
 * but we still guard against non-array garbage (old rows/manual DB edits) rather than letting
 * validators throw on `.filter`/`.forEach`.
 */
function toStudioGraph(nodes: unknown, edges: unknown): { nodes: StudioNode[]; edges: StudioEdge[] } {
  return {
    nodes: Array.isArray(nodes) ? (nodes as StudioNode[]) : [],
    edges: Array.isArray(edges) ? (edges as StudioEdge[]) : [],
  };
}

/** A single saved revision of a workflow, appended to `WorkflowMetadata.history` on every save. */
export interface WorkflowVersionSnapshot {
  version: number;
  timestamp: number;
  author: string;
  message: string;
  nodes: unknown;
  edges: unknown;
}

/**
 * A published-version archive entry, created by `publishWorkflow`/`rollbackToVersion` for the
 * content a publish/rollback is about to supersede — never for a version that was never actually
 * live. Backed by the dedicated Prisma `WorkflowVersion` table (see the model comment in
 * `prisma/schema.prisma` and `.agents/handoffs/onda-5/01-para-07-schema-workflow-version-
 * pronto.md`), one immutable row per (workflowId, version). This interface is the service-layer
 * return/input shape; `toPublishedWorkflowVersion` below converts a `WorkflowVersion` Prisma row
 * into it.
 *
 * Earlier in Onda 5 this was stored inline in `Workflow.metadata.publishedVersions` (interim
 * mechanism, before the dedicated table existed). That JSON is NOT migrated/backfilled into the
 * table — any workflow published before this change keeps its old archive frozen in `metadata`,
 * unread by the code below (per the handoff's explicit "sem backfill retroativo" decision).
 */
export interface PublishedWorkflowVersion {
  version: number;
  nodes: unknown;
  edges: unknown;
  metadata: Record<string, unknown>;
  publishedAt: string; // ISO 8601
  publishedBy: string | null;
}

function toPublishedWorkflowVersion(row: {
  version: number;
  nodes: unknown;
  edges: unknown;
  metadata: unknown;
  publishedAt: Date;
  publishedBy: string | null;
}): PublishedWorkflowVersion {
  return {
    version: row.version,
    nodes: row.nodes,
    edges: row.edges,
    metadata: (row.metadata as Record<string, unknown> | null) ?? {},
    publishedAt: row.publishedAt.toISOString(),
    publishedBy: row.publishedBy,
  };
}

/**
 * Shape of the Workflow.metadata Prisma `Json` field. `history` is the per-save draft trail
 * (every `saveWorkflow` call, published or not) — unaffected by this change, still stored inline.
 *
 * `publishedVersions` is kept here ONLY as the legacy shape of content archived before the
 * dedicated `WorkflowVersion` table existed (see `PublishedWorkflowVersion` above). Nothing in
 * this file writes to it anymore; it is never read by `listWorkflowVersions`/`rollbackToVersion`
 * either — a workflow published before this migration keeps that history frozen here, invisible
 * to the new code path, exactly as documented in the schema handoff.
 */
export interface WorkflowMetadata {
  history?: WorkflowVersionSnapshot[];
  /** @deprecated Legacy pre-WorkflowVersion-table archive. Frozen; no longer read or written. */
  publishedVersions?: PublishedWorkflowVersion[];
  [key: string]: unknown;
}

/**
 * Archives `versionToArchive`'s content as a new `WorkflowVersion` row, unless one already exists
 * for that (workflowId, version) pair — enforced by the DB's own `@@unique([workflowId, version])`
 * constraint (not just an in-memory check), so a genuine race between two concurrent publishes/
 * rollbacks for the same workflow can never produce two archive rows for the same version.
 * `Workflow.version` should only ever increase via `publishWorkflow`/`rollbackToVersion`, so a
 * collision should never happen in normal operation; if the constraint is hit anyway (race, or a
 * manual DB edit), we log and keep the already-archived row rather than throwing or duplicating.
 */
async function archivePublishedVersion(
  workflowId: string,
  versionToArchive: number,
  nodes: unknown,
  edges: unknown,
  metadata: unknown,
  publishedBy: string
): Promise<void> {
  try {
    await workflowRepository.createWorkflowVersion({
      workflowId,
      version: versionToArchive,
      nodes,
      edges,
      metadata,
      publishedBy,
    });
  } catch (err: any) {
    if (workflowRepository.isUniqueConstraintViolation(err)) {
      logger.error('Refusing to duplicate an already-archived workflow version', { workflowId, versionToArchive });
      return;
    }
    throw err;
  }
}

export function getWorkflow(organizationId: string, _version?: number) {
  return workflowRepository.findWorkflowForTenant(organizationId);
}

export async function getWorkflowHistory(organizationId: string) {
  const existing = await workflowRepository.findWorkflowForTenant(organizationId);
  if (!existing) return [];
  const metadata = existing.metadata as unknown as WorkflowMetadata;
  return metadata?.history || [];
}

export async function saveWorkflow(organizationId: string, userId: string, data: { name?: string; nodes?: unknown; edges?: unknown, commitMessage?: string }) {
  const existing = await workflowRepository.findWorkflowForTenant(organizationId);

  const metadata = (existing?.metadata as unknown as WorkflowMetadata) || {};
  const newVersion = (existing?.version || 0) + 1;

  const snapshot: WorkflowVersionSnapshot = {
    version: newVersion,
    timestamp: Date.now(),
    author: userId,
    message: data.commitMessage || `Update ${newVersion}`,
    nodes: data.nodes || existing?.nodes || [],
    edges: data.edges || existing?.edges || []
  };

  metadata.history = metadata.history || [];
  metadata.history.push(snapshot);

  // Every structural save is unvalidated new content. Even if the row used to be active, the
  // write goes back to draft and must cross publishWorkflow again before production can see it.
  return workflowRepository.upsertWorkflow(organizationId, userId, existing?.id ?? null, {
    ...data,
    metadata,
    version: newVersion,
    status: 'draft',
  });
}

export async function updateWorkflow(organizationId: string, userId: string, data: { name?: string; nodes?: unknown; edges?: unknown }) {
  const existing = await workflowRepository.findWorkflowForTenant(organizationId);
  if (!existing) throw new NotFoundError('Workflow não encontrado para atualização.');

  const structuralChange = data.nodes !== undefined || data.edges !== undefined;

  return workflowRepository.upsertWorkflow(organizationId, userId, existing.id, {
    name: data.name ?? existing.name,
    nodes: data.nodes ?? existing.nodes,
    edges: data.edges ?? existing.edges,
    status: structuralChange ? 'draft' : undefined,
  });
}

/**
 * The single gate a workflow must pass through to become `active`.
 *
 * Two independent validations happen server-side against the persisted graph:
 * 1. `ValidationEngine` checks graph correctness (start node, reachability, dead ends, cycles,
 *    required node configuration, etc.).
 * 2. `validateRuntimeCompatibility` checks whether the production telephony runtime can honestly
 *    execute every node/branch. A visually valid graph is NOT activated if it depends on a node
 *    whose runtime executor does not exist yet.
 *
 * This prevents the Studio from advertising a successful publish for a graph that real calls
 * would silently ignore.
 *
 * Before the new content goes live, the content it is about to supersede is archived (see
 * `archivePublishedVersion`/`PublishedWorkflowVersion`) under its own (pre-increment) version
 * number, then `Workflow.version` is incremented. A running phone call already mid-conversation
 * is unaffected either way — `telephonyService.ts` snapshots the workflow into
 * `PhoneSessionMetadata.workflow` at call start and never re-reads the live row mid-call.
 */
export async function publishWorkflow(organizationId: string, userId: string) {
  const existing = await workflowRepository.findWorkflowForTenant(organizationId);
  if (!existing) throw new NotFoundError('Nenhum fluxo encontrado para publicar.');

  const { nodes, edges } = toStudioGraph(existing.nodes, existing.edges);
  const graphResult = validationEngine.validate(nodes, edges);
  const runtimeIssues = validateRuntimeCompatibility(nodes, edges);
  const issues = [...graphResult.issues, ...runtimeIssues];

  if (!graphResult.isValid || runtimeIssues.some((issue) => issue.type === 'error')) {
    throw new ValidationFailedError(issues);
  }

  await archivePublishedVersion(existing.id, existing.version, existing.nodes, existing.edges, existing.metadata, userId);

  return workflowRepository.upsertWorkflow(organizationId, userId, existing.id, {
    status: 'active',
    version: existing.version + 1,
  });
}

/**
 * Published-version archive for one workflow (tenant-scoped by `workflowId` + `organizationId`,
 * never trusting `workflowId` alone — see `workflowRepository.findWorkflowByIdForTenant`).
 * Newest first. Returns `[]` (never a 404) for a workflow that has never been published, since
 * "no versions yet" is a legitimate, non-error state.
 */
export async function listWorkflowVersions(organizationId: string, workflowId: string): Promise<PublishedWorkflowVersion[]> {
  const workflow = await workflowRepository.findWorkflowByIdForTenant(workflowId, organizationId);
  if (!workflow) throw new NotFoundError('Workflow não encontrado.');

  const versions = await workflowRepository.findWorkflowVersionsForWorkflow(workflow.id);
  return versions.map(toPublishedWorkflowVersion);
}

/**
 * Rollback = republish an archived version's content as a BRAND NEW version — never rewrites the
 * version number that content was originally published under, so history stays linear and
 * auditable (the old version's archive entry is untouched; a new one is appended for whatever was
 * live immediately before the rollback).
 *
 * Passes through the exact same two gates as `publishWorkflow` (`ValidationEngine` +
 * `validateRuntimeCompatibility`), evaluated against the ARCHIVED content, not the current one —
 * a version that used to be valid can be rejected today if the runtime capability it depended on
 * has since been removed (see `docs/patterns/workflow-execution-contract.md` §2); rolling back to
 * it must fail the same way a fresh publish of that graph would, never apply it half-broken.
 */
export async function rollbackToVersion(organizationId: string, userId: string, workflowId: string, version: number) {
  const existing = await workflowRepository.findWorkflowByIdForTenant(workflowId, organizationId);
  if (!existing) throw new NotFoundError('Workflow não encontrado.');

  const target = await workflowRepository.findWorkflowVersion(existing.id, version);
  if (!target) throw new NotFoundError(`Versão ${version} não encontrada para este fluxo.`);

  const { nodes, edges } = toStudioGraph(target.nodes, target.edges);
  const graphResult = validationEngine.validate(nodes, edges);
  const runtimeIssues = validateRuntimeCompatibility(nodes, edges);
  const issues = [...graphResult.issues, ...runtimeIssues];

  if (!graphResult.isValid || runtimeIssues.some((issue) => issue.type === 'error')) {
    throw new ValidationFailedError(issues);
  }

  await archivePublishedVersion(existing.id, existing.version, existing.nodes, existing.edges, existing.metadata, userId);

  return workflowRepository.upsertWorkflow(organizationId, userId, existing.id, {
    nodes: target.nodes,
    edges: target.edges,
    metadata: target.metadata,
    status: 'active',
    version: existing.version + 1,
  });
}

export async function restoreWorkflowVersion(organizationId: string, userId: string, versionToRestore: number) {
  const existing = await workflowRepository.findWorkflowForTenant(organizationId);
  if (!existing) throw new NotFoundError('Workflow não encontrado.');

  const metadata = existing.metadata as unknown as WorkflowMetadata;
  const history = metadata?.history || [];
  const snapshot = history.find((h) => h.version === versionToRestore);

  if (!snapshot) throw new NotFoundError('Versão não encontrada.');

  return saveWorkflow(organizationId, userId, {
    nodes: snapshot.nodes,
    edges: snapshot.edges,
    commitMessage: `Restaurado para a versão ${versionToRestore}`
  });
}

export async function removeWorkflow(organizationId: string) {
  const existing = await workflowRepository.findWorkflowForTenant(organizationId);
  if (!existing) throw new NotFoundError('Nenhum fluxo encontrado para exclusão.');
  await workflowRepository.deleteWorkflow(existing.id);
  return existing;
}

export async function duplicateWorkflow(organizationId: string, userId: string, _sourceWorkflowId: string) {
  const existing = await workflowRepository.findWorkflowForTenant(organizationId);
  if (!existing) throw new NotFoundError('Workflow de origem não encontrado.');

  return workflowRepository.upsertWorkflow(organizationId, userId, null, {
    name: `${existing.name} (Cópia)`,
    nodes: existing.nodes,
    edges: existing.edges
  });
}

import type { Request, Response } from 'express';
import { z } from 'zod';
import { sessionSchema } from '../validators/index.js';
import { listSessions, createSession, updateSession, deleteSession, NotFoundError } from '../services/sessionService.js';

const updateSessionSchema = z.object({
  status: z.string().optional(),
  metadata: z.record(z.string(), z.any()).optional(),
});

export async function listSessionsHandler(req: Request, res: Response) {
  const sessions = await listSessions(req.organizationId!, req.user?.id);
  return res.json({ sessions });
}

export async function createSessionHandler(req: Request, res: Response) {
  const parsed = sessionSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  const session = await createSession(req.organizationId!, req.user?.id, parsed.data);
  return res.json({ success: true, session });
}

export async function updateSessionHandler(req: Request, res: Response) {
  const parsed = updateSessionSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  try {
    const session = await updateSession(String(req.params.id), req.organizationId!, req.user?.id, parsed.data);
    return res.json({ success: true, session });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

export async function deleteSessionHandler(req: Request, res: Response) {
  try {
    await deleteSession(String(req.params.id), req.organizationId!, req.user?.id);
    return res.json({ success: true, message: 'Sessão encerrada e removida com sucesso.' });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

import type { Request, Response } from 'express';
import twilio from 'twilio';
import * as telephonyService from '../services/telephonyService.js';
import type { TransferDetails, VoiceOverride } from '../services/workflowRuntimeService.js';
import { logger } from '@/lib/logger';

const { VoiceResponse } = twilio.twiml;

// Twilio's own generated typings (`VoiceResponse.SayAttributes`) narrow `language`/`voice` to
// large-but-closed literal unions of names Twilio actually recognizes. `VoiceOverride` (see
// `.agents/handoffs/onda-6/04-para-05-voiceOverride-contrato.md`) only ever carries a value drawn
// from `workflowRuntimeService.ts`'s own `KNOWN_TWILIO_VOICE_NAMES` table — i.e. a genuine Twilio
// voice name — so this alias plus the narrowing casts in `sayOptionsFor` below just bridge two
// string types that are runtime-compatible by construction; it is not a blind `any`/`unknown`
// escape hatch.
type SayAttributes = Parameters<InstanceType<typeof VoiceResponse>['say']>[0];

function sendTwiml(res: Response, twiml: InstanceType<typeof VoiceResponse>) {
  res.type('text/xml').send(twiml.toString());
}

function gatherActionUrl(sessionId: string): string {
  return `/api/telephony/twilio/gather?sessionId=${encodeURIComponent(sessionId)}`;
}

function dialActionUrl(sessionId: string): string {
  return `/api/telephony/twilio/dial-status?sessionId=${encodeURIComponent(sessionId)}`;
}

/**
 * Builds the attributes for a `<Say>`/`<Gather><Say>` from an optional `voiceOverride` produced by
 * `prepareWorkflowTurn`/`resumeAfterTool` (see
 * `.agents/handoffs/onda-6/04-para-05-voiceOverride-contrato.md`). Falls back to the fixed
 * `pt-BR` default Twilio voice used everywhere else in this controller when no override is
 * present (no `voice` node reached yet, or its configured voice has no known Twilio mapping).
 */
function sayOptionsFor(voiceOverride?: VoiceOverride): SayAttributes {
  if (!voiceOverride) return { language: 'pt-BR' };
  return {
    language: (voiceOverride.language ?? 'pt-BR') as SayAttributes['language'],
    voice: voiceOverride.voice as SayAttributes['voice'],
  };
}

type DialAttributes = Parameters<InstanceType<typeof VoiceResponse>['dial']>[0];

/**
 * Builds the attributes for the `<Dial>` a `TransferDetails` (see
 * `.agents/handoffs/onda-6/04-para-05-transferDetails-contrato.md`) produces. `timeoutSec`/
 * `record` are already validated/defaulted on the runtime side (Agente 04) — this only maps them
 * onto Twilio's own attribute names/values (`record: true` → the `'record-from-answer'` TwiML
 * value; `false` omits the attribute, matching Twilio's own default of not recording).
 * When `sessionId` is provided, sets `action` callback to observe transfer status (completed/busy/no-answer).
 */
function dialOptionsFor(transferDetails: TransferDetails, sessionId?: string): DialAttributes {
  return {
    timeout: transferDetails.timeoutSec,
    record: transferDetails.record ? 'record-from-answer' : undefined,
    action: sessionId ? dialActionUrl(sessionId) : undefined,
    method: 'POST',
  };
}

export async function incomingCallHandler(req: Request, res: Response) {
  const callSid = String(req.body.CallSid || '');
  const from = String(req.body.From || '');
  const to = String(req.body.To || '');

  const twiml = new VoiceResponse();
  const result = await telephonyService.startCall({ callSid, from, to });

  if (!result.configured) {
    twiml.say({ language: 'pt-BR' }, 'Este número ainda não está configurado para atendimento. Por favor, tente novamente mais tarde.');
    twiml.hangup();
    return sendTwiml(res, twiml);
  }

  const gather = twiml.gather({
    input: ['speech'],
    action: gatherActionUrl(result.sessionId),
    method: 'POST',
    language: 'pt-BR',
    speechTimeout: 'auto',
  });
  gather.say({ language: 'pt-BR' }, result.greeting);

  // Reached if the caller never speaks and Twilio falls through the <Gather> without redirecting.
  twiml.say({ language: 'pt-BR' }, telephonyService.messages.goodbye);
  sendTwiml(res, twiml);
}

/**
 * TwiML for a call we placed ourselves. Twilio requests this once the prospect picks up; the
 * session was created before dialing, so its id travels in the query string (the same trick the
 * gather flow uses) instead of being looked up by CallSid.
 */
export async function outboundCallHandler(req: Request, res: Response) {
  const sessionId = String(req.query.sessionId || '');
  const callSid = String(req.body.CallSid || '');
  const twiml = new VoiceResponse();

  const result = await telephonyService.startOutboundCall({ sessionId, callSid });

  if (!result.found) {
    logger.warn('Outbound TwiML requested for an unknown session', { sessionId, callSid });
    twiml.hangup();
    return sendTwiml(res, twiml);
  }

  const gather = twiml.gather({
    input: ['speech'],
    action: gatherActionUrl(sessionId),
    method: 'POST',
    language: 'pt-BR',
    speechTimeout: 'auto',
  });
  gather.say({ language: 'pt-BR' }, result.greeting);

  // Reached when the person never speaks — e.g. an answering machine picked up.
  twiml.say({ language: 'pt-BR' }, telephonyService.messages.goodbye);
  sendTwiml(res, twiml);
}

export async function gatherHandler(req: Request, res: Response) {
  const sessionId = String(req.query.sessionId || '');
  const speechResult = String(req.body.SpeechResult || '').trim();
  const twiml = new VoiceResponse();

  if (!sessionId) {
    twiml.say({ language: 'pt-BR' }, telephonyService.messages.goodbye);
    twiml.hangup();
    return sendTwiml(res, twiml);
  }

  if (!speechResult) {
    const gather = twiml.gather({
      input: ['speech'],
      action: gatherActionUrl(sessionId),
      method: 'POST',
      language: 'pt-BR',
      speechTimeout: 'auto',
    });
    gather.say({ language: 'pt-BR' }, telephonyService.messages.reprompt);
    twiml.say({ language: 'pt-BR' }, telephonyService.messages.goodbye);
    return sendTwiml(res, twiml);
  }

  const result = await telephonyService.handleTurn({ sessionId, speechResult });
  if (!result.found) {
    twiml.say({ language: 'pt-BR' }, telephonyService.messages.goodbye);
    twiml.hangup();
    return sendTwiml(res, twiml);
  }

  const sayOptions = sayOptionsFor(result.voiceOverride);

  // A published `human_handoff` node (see
  // `.agents/handoffs/onda-6/04-para-05-transferDetails-contrato.md`) has no workflow resumption —
  // a real telephony bridge takes over the call, so this speaks `transferDetails.message` and
  // dials `transferDetails.to` for real instead of opening another `<Gather>`, regardless of
  // `result.shouldEnd` (the runtime always reports `false` there since it never marks the workflow
  // itself "ended" on a transfer — see the contract doc).
  if (result.transferDetails) {
    twiml.say(sayOptions, result.reply);
    twiml.dial(dialOptionsFor(result.transferDetails, sessionId), result.transferDetails.to);
    return sendTwiml(res, twiml);
  }

  // A published Studio `end` node is a real termination boundary. Do not create another Gather
  // after it; speak the final response once and close the call deterministically.
  if (result.shouldEnd) {
    twiml.say(sayOptions, result.reply);
    twiml.hangup();
    return sendTwiml(res, twiml);
  }

  const gather = twiml.gather({
    input: ['speech'],
    action: gatherActionUrl(sessionId),
    method: 'POST',
    language: 'pt-BR',
    speechTimeout: 'auto',
  });
  gather.say(sayOptions, result.reply);
  sendTwiml(res, twiml);
}

export async function statusCallbackHandler(req: Request, res: Response) {
  const callSid = String(req.body.CallSid || '');
  const status = String(req.body.CallStatus || '');
  const durationSeconds = Number(req.body.CallDuration || 0);

  try {
    if (callSid && status) {
      await telephonyService.endCall({ callSid, status, durationSeconds });
    }
  } catch (err: any) {
    logger.error('Failed to finalize call from status callback', err);
  }

  return res.status(200).send();
}

/**
 * Handles the action callback from Twilio when a <Dial> (e.g. human_handoff) completes or fails.
 * Captures DialCallStatus (completed, busy, no-answer, failed, canceled) and logs duration.
 * If not completed, provides a graceful Portuguese voice fallback message before hanging up.
 */
export async function dialStatusHandler(req: Request, res: Response) {
  const sessionId = String(req.query.sessionId || '');
  const dialCallStatus = String(req.body.DialCallStatus || '');
  const dialCallDuration = Number(req.body.DialCallDuration || 0);
  const twiml = new VoiceResponse();

  logger.info('Twilio Dial status callback received', {
    sessionId,
    dialCallStatus,
    dialCallDuration,
  });

  if (dialCallStatus === 'completed') {
    twiml.hangup();
    return sendTwiml(res, twiml);
  }

  // When human handoff was unanswered, busy, or failed, speak a clean fallback
  twiml.say(
    { language: 'pt-BR' },
    'Não foi possível conectar com um atendente no momento. Por favor, tente novamente mais tarde.'
  );
  twiml.hangup();
  sendTwiml(res, twiml);
}

import type { Request, Response } from 'express';
import { createUserSchema, updateUserSchema } from '../validators/index.js';
import { listUsers, createUserInTenant, updateUserProfile, deleteUser, anonymizeUserData, UserServiceError } from '../services/userService.js';
import { writeAuditLog } from '../services/audit.js';

export async function listUsersHandler(req: Request, res: Response) {
  const users = await listUsers(req.organizationId!);
  return res.json({ users });
}

export async function createUserHandler(req: Request, res: Response) {
  const parsed = createUserSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  try {
    const user = await createUserInTenant(req.organizationId!, parsed.data);
    writeAuditLog(req.organizationId, req.user?.id, 'USER_CREATE_BY_ADMIN', { targetUserId: user.id, email: user.email });
    return res.json({ success: true, user });
  } catch (err: any) {
    if (err instanceof UserServiceError) return res.status(err.status).json({ error: err.message });
    throw err;
  }
}

export async function updateUserHandler(req: Request, res: Response) {
  const parsed = updateUserSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  try {
    await updateUserProfile(String(req.params.id), req.organizationId!, req.user!, parsed.data);
    writeAuditLog(req.organizationId, req.user?.id, 'USER_UPDATE', { targetUserId: String(req.params.id) });
    return res.json({ success: true, message: 'Perfil atualizado com sucesso.' });
  } catch (err: any) {
    if (err instanceof UserServiceError) return res.status(err.status).json({ error: err.message });
    throw err;
  }
}

export async function deleteUserHandler(req: Request, res: Response) {
  try {
    await deleteUser(String(req.params.id), req.organizationId!, req.user?.id);
    writeAuditLog(req.organizationId, req.user?.id, 'USER_DELETE', { targetUserId: String(req.params.id) });
    return res.json({ success: true, message: 'Usuário excluído com sucesso.' });
  } catch (err: any) {
    if (err instanceof UserServiceError) return res.status(err.status).json({ error: err.message });
    throw err;
  }
}

// LGPD technical erasure mechanism (Art. 18, VI, Lei 13.709/2018): irreversibly scrubs the
// account's personal data (email, company name, credential) instead of merely hiding the row.
// A user may invoke this on their own account (self-service data-subject request); an admin may
// invoke it on behalf of a titular within the same tenant.
export async function anonymizeUserHandler(req: Request, res: Response) {
  try {
    await anonymizeUserData(String(req.params.id), req.organizationId!, req.user!);
    writeAuditLog(req.organizationId, req.user?.id, 'USER_DATA_ANONYMIZED', { targetUserId: String(req.params.id) });
    return res.json({ success: true, message: 'Dados pessoais anonimizados com sucesso, conforme solicitação do titular (LGPD).' });
  } catch (err: any) {
    if (err instanceof UserServiceError) return res.status(err.status).json({ error: err.message });
    throw err;
  }
}

import type { Request, Response } from 'express';
import { outboundCallSchema } from '../validators/index.js';
import { initiateOutboundCall, AgentNotFoundError, DuplicateCallError } from '../services/outboundCallService.js';
import { TwilioNotConfiguredError } from '../services/twilioClient.js';
import { logger } from '@/lib/logger';

export async function initiateOutboundCallHandler(req: Request, res: Response) {
  const parsed = outboundCallSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  try {
    const result = await initiateOutboundCall({
      organizationId: req.organizationId!,
      agentId: parsed.data.agentId,
      targetNumber: parsed.data.targetNumber,
      context: parsed.data.context,
      callbackUrl: parsed.data.callbackUrl,
    });

    return res.status(202).json({ success: true, ...result });
  } catch (err: any) {
    if (err instanceof AgentNotFoundError) {
      return res.status(404).json({ error: err.message });
    }
    if (err instanceof DuplicateCallError) {
      return res.status(409).json({ error: err.message });
    }
    if (err instanceof TwilioNotConfiguredError) {
      // A deployment gap, not a bad request — surfaced distinctly so an automated dialer can tell
      // "this will never work until an operator acts" from "this number failed".
      return res.status(503).json({ error: err.message });
    }

    logger.error('[VoiceOutbound] Failed to initiate call', err);
    return res.status(502).json({ error: 'Não foi possível iniciar a chamada no provedor de telefonia.' });
  }
}

import type { Request, Response } from 'express';
import { createWebhookEndpointSchema } from '../validators/index.js';
import { writeAuditLog } from '../services/audit.js';
import {
  WebhookEndpointServiceError,
  createWebhookEndpointForTenant,
  listWebhookEndpointsForTenant,
  deleteWebhookEndpointForTenant,
  regenerateWebhookEndpointSecret,
} from '../services/webhookEndpointService.js';

// Shared by every handler below: WebhookEndpointServiceError carries the right HTTP status for a
// business-rule rejection (limit reached, not found). Returns true when it handled the error
// (caller returns immediately); false means the caller should rethrow.
function handleKnownError(err: unknown, res: Response): boolean {
  if (err instanceof WebhookEndpointServiceError) {
    return res.status(err.status).json({ error: err.message });
    return true;
  }
  return false;
}

// POST /api/developers/webhooks — creates a new tenant-scoped webhook endpoint. The plaintext
// `secret` is present in this response ONLY: it is never stored, never logged and never
// retrievable again afterwards (AGENTS.md §13) — only regenerating it (below) produces a new one.
export async function createWebhookEndpointHandler(req: Request, res: Response) {
  const parsed = createWebhookEndpointSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  try {
    const endpoint = await createWebhookEndpointForTenant(req.organizationId as string, parsed.data);
    writeAuditLog(req.organizationId, req.user?.id, 'WEBHOOK_ENDPOINT_CREATE', {
      webhookEndpointId: endpoint.id,
      url: endpoint.url,
      events: endpoint.events,
    });
    return res.status(201).json({
      webhookEndpoint: {
        id: endpoint.id,
        url: endpoint.url,
        events: endpoint.events,
        active: endpoint.active,
        createdAt: endpoint.createdAt,
      },
      secret: endpoint.secret,
    });
  } catch (err: any) {
    if (handleKnownError(err, res)) return;
    throw err;
  }
}

// GET /api/developers/webhooks — metadata only (url, events, active, delivery bookkeeping). Never
// includes the secret or its hash.
export async function listWebhookEndpointsHandler(req: Request, res: Response) {
  try {
    const webhookEndpoints = await listWebhookEndpointsForTenant(req.organizationId as string);
    return res.json({ webhookEndpoints });
  } catch (err: any) {
    if (handleKnownError(err, res)) return;
    throw err;
  }
}

// DELETE /api/developers/webhooks/:id — tenant-scoped: an admin from tenant A can never delete, or
// even discover the existence of, an endpoint belonging to tenant B.
export async function deleteWebhookEndpointHandler(req: Request, res: Response) {
  try {
    await deleteWebhookEndpointForTenant(req.organizationId as string, String(req.params.id));
    writeAuditLog(req.organizationId, req.user?.id, 'WEBHOOK_ENDPOINT_DELETE', { webhookEndpointId: req.params.id });
    return res.json({ success: true });
  } catch (err: any) {
    if (handleKnownError(err, res)) return;
    throw err;
  }
}

// POST /api/developers/webhooks/:id/regenerate-secret — invalidates the current secret and mints
// a new one, returned in plaintext exactly once, same rule as creation.
export async function regenerateWebhookEndpointSecretHandler(req: Request, res: Response) {
  try {
    const endpoint = await regenerateWebhookEndpointSecret(req.organizationId as string, String(req.params.id));
    writeAuditLog(req.organizationId, req.user?.id, 'WEBHOOK_ENDPOINT_REGENERATE_SECRET', {
      webhookEndpointId: endpoint.id,
    });
    return res.json({
      webhookEndpoint: {
        id: endpoint.id,
        url: endpoint.url,
        events: endpoint.events,
        active: endpoint.active,
        createdAt: endpoint.createdAt,
      },
      secret: endpoint.secret,
    });
  } catch (err: any) {
    if (handleKnownError(err, res)) return;
    throw err;
  }
}

import type { Request, Response } from 'express';
import { saveWorkflowSchema } from '../validators/index.js';
import { getWorkflow, saveWorkflow, updateWorkflow, removeWorkflow, getWorkflowHistory, restoreWorkflowVersion, duplicateWorkflow, publishWorkflow, listWorkflowVersions, rollbackToVersion, NotFoundError, ValidationFailedError } from '../services/workflowService.js';
import { writeAuditLog } from '../services/audit.js';

export async function getWorkflowHandler(req: Request, res: Response) {
  const workflow = await getWorkflow(req.organizationId as string);
  return res.json({ workflow: workflow || null });
}

export async function saveWorkflowHandler(req: Request, res: Response) {
  const parsed = saveWorkflowSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  const data = { ...parsed.data, commitMessage: req.body.commitMessage };
  const workflow = await saveWorkflow(req.organizationId as string, req.user?.id, data);
  writeAuditLog(req.organizationId, req.user?.id, 'WORKFLOW_SAVE', { workflowId: workflow.id, name: workflow.name, version: workflow.version });
  return res.json({ success: true, workflow });
}

export async function updateWorkflowHandler(req: Request, res: Response) {
  const parsed = saveWorkflowSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: parsed.error.issues[0].message });

  try {
    const workflow = await updateWorkflow(req.organizationId as string, req.user?.id, parsed.data);
    writeAuditLog(req.organizationId, req.user?.id, 'WORKFLOW_UPDATE', { workflowId: workflow.id, name: workflow.name });
    return res.json({ success: true, workflow });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

export async function deleteWorkflowHandler(req: Request, res: Response) {
  try {
    const deleted = await removeWorkflow(req.organizationId as string);
    writeAuditLog(req.organizationId, req.user?.id, 'WORKFLOW_DELETE', { workflowId: deleted.id });
    return res.json({ success: true, message: 'Fluxo removido com sucesso.' });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

export async function getWorkflowHistoryHandler(req: Request, res: Response) {
  const history = await getWorkflowHistory(req.organizationId as string);
  return res.json({ history });
}

export async function restoreWorkflowVersionHandler(req: Request, res: Response) {
  const { version } = req.body;
  if (!version) return res.status(400).json({ error: 'Versão é obrigatória.' });

  try {
    const workflow = await restoreWorkflowVersion(req.organizationId as string, req.user?.id, Number(version));
    writeAuditLog(req.organizationId, req.user?.id, 'WORKFLOW_RESTORE', { workflowId: workflow.id, restoredVersion: version });
    return res.json({ success: true, workflow });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

export async function publishWorkflowHandler(req: Request, res: Response) {
  try {
    const workflow = await publishWorkflow(req.organizationId as string, req.user?.id);
    writeAuditLog(req.organizationId, req.user?.id, 'WORKFLOW_PUBLISH', { workflowId: workflow.id, version: workflow.version });
    return res.json({ success: true, workflow });
  } catch (err: any) {
    if (err instanceof ValidationFailedError) {
      // 422: request was well-formed, but the workflow content fails ValidationEngine. The
      // frontend (TopBar/Inspector) must surface `issues` verbatim, never treat this as a
      // generic failure and never retry-as-success.
      return res.status(422).json({ error: err.message, issues: err.issues });
    }
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

// GET /workflow/:id/versions — published-version archive for one workflow, tenant-scoped by
// `req.organizationId` (never the raw `:id` param alone — see workflowRepository.findWorkflowByIdForTenant
// and AGENTS.md §15). Returns 404 rather than an empty tenant-agnostic list when the workflow
// belongs to another tenant or does not exist, so cross-tenant existence can never be inferred
// from the response shape.
export async function listWorkflowVersionsHandler(req: Request, res: Response) {
  try {
    const versions = await listWorkflowVersions(req.organizationId as string, String(req.params.id));
    return res.json({ versions });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

// POST /workflow/:id/versions/:version/rollback — republishes an archived version's content as a
// brand new version. Goes through the same publish gates as publishWorkflowHandler and maps a
// gate failure to the same 422 shape.
export async function rollbackWorkflowVersionHandler(req: Request, res: Response) {
  const versionParam = Number(req.params.version);
  if (!Number.isInteger(versionParam) || versionParam < 1) {
    return res.status(400).json({ error: 'Versão inválida.' });
  }

  try {
    const workflow = await rollbackToVersion(req.organizationId as string, req.user?.id, String(req.params.id), versionParam);
    writeAuditLog(req.organizationId, req.user?.id, 'WORKFLOW_ROLLBACK', {
      workflowId: workflow.id,
      rolledBackToVersion: versionParam,
      newVersion: workflow.version,
    });
    return res.json({ success: true, workflow });
  } catch (err: any) {
    if (err instanceof ValidationFailedError) {
      return res.status(422).json({ error: err.message, issues: err.issues });
    }
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

export async function duplicateWorkflowHandler(req: Request, res: Response) {
  try {
    const workflow = await duplicateWorkflow(req.organizationId as string, req.user?.id, req.body.sourceId); // mock param
    writeAuditLog(req.organizationId, req.user?.id, 'WORKFLOW_DUPLICATE', { originalId: req.body.sourceId, newId: workflow.id });
    return res.json({ success: true, workflow });
  } catch (err: any) {
    if (err instanceof NotFoundError) return res.status(404).json({ error: err.message });
    throw err;
  }
}

